import { useCallback, useEffect, useMemo, useState } from 'react';
import { useLocation, useNavigate, useSearchParams } from 'react-router-dom';
import Header from '@/components/Header';
import CategoryOverview from '@/components/CategoryOverview';
import PaperCard from '@/components/PaperCard';
import FilterBar from '@/components/FilterBar';
import StatsBar from '@/components/StatsBar';
import LandscapeVisualization from '@/components/LandscapeVisualization';
import AddPaperModal from '@/components/AddPaperModal';
import ProposePapersModal from '@/components/ProposePapersModal';
import { loadPapers, loadConfig } from '@/lib/data';
import { isAnonymized } from '@/lib/filters';
import { matchesFilters } from '@/lib/facets';
import { useFilters } from '@/lib/filterState';
import { makeColorFor, makeShapeFor } from '@/lib/colors';
import { ShapesToggle, useShapes } from '@/lib/shapes';
import { humanize } from '@/lib/humanize';
import { DIMENSIONS, MISSING, getDimension, unitValues } from '@/lib/analysis';

// Dimensions the tiles and landscape colours can be grouped by. Year and track
// are left out: they are already the landscape's two axes.
const GROUP_OPTIONS = DIMENSIONS.filter((d) => d.key !== 'year' && d.key !== 'track')
  .map((d) => ({ key: d.key, label: humanize(d.key) }));
const DEFAULT_GROUP = 'type_of_artifact';

export default function PapersPage() {
  const navigate = useNavigate();
  const location = useLocation();
  const analysisSelection = location.state?.analysisSelection || null;
  const selectionIds = useMemo(
    () => (analysisSelection ? new Set(analysisSelection.ids) : null),
    [analysisSelection]
  );
  const clearSelection = () => navigate('/', { replace: true, state: null });
  const [papers, setPapers] = useState(null);
  const [config, setConfig] = useState(null);
  const { filters, toggle } = useFilters();
  const [query, setQuery] = useState('');
  const [compareMode, setCompareMode] = useState(false);
  const [compareIds, setCompareIds] = useState([]);
  const [showAddPaper, setShowAddPaper] = useState(false);
  const [showPropose, setShowPropose] = useState(false);

  useEffect(() => {
    Promise.all([loadPapers(), loadConfig()]).then(([p, c]) => {
      setPapers(p);
      setConfig(c);
    });
  }, []);

  // The modal stays open on its own "success" step (with the option to
  // propose the paper for the shared dataset) — this just refreshes the
  // list underneath so the new paper is already pinned at the top by the
  // time the modal closes.
  const handlePaperAdded = () => {
    loadPapers().then(setPapers);
  };

  const [params, setParams] = useSearchParams();
  const groupKey = GROUP_OPTIONS.some((o) => o.key === params.get('group')) ? params.get('group') : DEFAULT_GROUP;
  const setGroupKey = (key) => setParams((prev) => {
    const p = new URLSearchParams(prev);
    if (key === DEFAULT_GROUP) p.delete('group'); else p.set('group', key);
    return p;
  }, { replace: true, state: location.state });

  const colorFor = useMemo(() => makeColorFor(config || {}, papers), [config, papers]);
  const artifactColors = useMemo(
    () => Object.fromEntries((config?.typesOfArtifact || []).map((t) => [t.id, t.color])),
    [config]
  );
  const { shapes } = useShapes();
  const shapeFor = useMemo(() => (shapes ? makeShapeFor(config || {}, papers) : null), [shapes, config, papers]);
  const groupValueOf = useCallback((paper) => {
    const dim = getDimension(groupKey);
    return unitValues({ paper, artifacts: paper.contribution?.artifacts || [] }, dim).find((v) => v !== MISSING);
  }, [groupKey]);
  const landscapeColorOf = useCallback((paper) => {
    const first = groupValueOf(paper);
    return first ? colorFor(groupKey, first) : null;
  }, [groupKey, groupValueOf, colorFor]);
  const landscapeShapeOf = useMemo(() => {
    if (!shapeFor) return null;
    return (paper) => {
      const first = groupValueOf(paper);
      return first ? shapeFor(groupKey, first) : null;
    };
  }, [shapeFor, groupKey, groupValueOf]);

  const matchesScope = useCallback((paper, exceptKey = null) => {
    if (selectionIds && !selectionIds.has(paper._id)) return false;
    if (!matchesFilters(paper, filters, exceptKey)) return false;
    const q = query.trim().toLowerCase();
    if (!q) return true;
    const haystack = [
      paper.metadata.title,
      ...(paper.metadata.authors || []),
      ...(paper.contribution?.keywords || []),
    ]
      .join(' ')
      .toLowerCase();
    return haystack.includes(q);
  }, [filters, query, selectionIds]);

  const filtered = useMemo(() => (papers ? papers.filter((p) => matchesScope(p)) : []), [papers, matchesScope]);
  const tilePapers = useMemo(
    () => (papers ? papers.filter((p) => matchesScope(p, groupKey)) : []),
    [papers, matchesScope, groupKey]
  );

  // Anonymized papers (outside the public sample, no title/authors) still
  // count toward the landscape/graph visualizations but are left out of the
  // browsable paper list — there's nothing to identify them by. Papers added
  // by the visitor float to the top, most-recently-added first.
  const sidebarPapers = useMemo(() => {
    const list = filtered.filter((p) => !isAnonymized(p));
    return [...list].sort((a, b) => {
      if (Boolean(a._userAdded) !== Boolean(b._userAdded)) return a._userAdded ? -1 : 1;
      if (a._userAdded && b._userAdded) return (b._userKey || '').localeCompare(a._userKey || '');
      return 0;
    });
  }, [filtered]);

  const toggleGroupValue = (id) => toggle(groupKey, id);

  const highlightIds = useMemo(
    () => (papers && filtered.length !== papers.length ? new Set(filtered.map((p) => p._id)) : null),
    [papers, filtered]
  );

  const toggleCompare = (id) => {
    setCompareIds((prev) => (prev.includes(id) ? prev.filter((i) => i !== id) : [...prev, id]));
  };

  if (!papers || !config) {
    return (
      <div className="main-layout">
        <div className="loading">
          <div className="loading__spinner" />
          <p>Loading...</p>
        </div>
      </div>
    );
  }

  const labels = config.visualization?.labels || {};

  return (
    <div className="main-layout">
      <Header config={config} />
      <main className="main-content">
        <FilterBar
          papers={papers}
          config={config}
          searchActive={query.trim() !== ''}
          onClearSearch={() => setQuery('')}
          search={config.features?.search !== false && (
            <input
              type="search"
              placeholder="Search title, author, keyword…"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              className="toolbar__search fb-search__input"
              aria-label="Search papers"
            />
          )}
        />

        <div className="papers-layout">
          <div className="papers-layout__main">
            {analysisSelection && (() => {
              const total = analysisSelection.ids.length;
              const named = papers.filter((p) => selectionIds.has(p._id) && !isAnonymized(p)).length;
              return (
                <div className="analysis-selection" role="status">
                  <div className="analysis-selection__text">
                    <span className="analysis-selection__eyebrow">Selected in Patterns &amp; Trends</span>
                    <strong>{analysisSelection.label}</strong>
                    <span className="analysis-selection__meta">
                      {total} {total === 1 ? 'paper' : 'papers'}
                      {total - named > 0 && ` · ${named} with title listed, ${total - named} anonymised (shown in the timeline)`}
                      {analysisSelection.note && ` · ${analysisSelection.note}`}
                    </span>
                  </div>
                  <div className="analysis-selection__actions">
                    <button type="button" className="btn btn--secondary btn--sm" onClick={() => navigate(analysisSelection.back || '/analysis')}>
                      ← Back to Patterns &amp; Trends
                    </button>
                    <button type="button" className="btn btn--ghost btn--sm" onClick={clearSelection}>
                      Show All Papers
                    </button>
                  </div>
                </div>
              );
            })()}
            {config.features?.stats !== false && <StatsBar papers={filtered} />}

            <CategoryOverview
              dimKey={groupKey}
              dimOptions={GROUP_OPTIONS}
              onDimChange={setGroupKey}
              papers={tilePapers}
              config={config}
              colorFor={colorFor}
              shapeFor={shapeFor}
              selected={filters[groupKey] || []}
              onToggle={toggleGroupValue}
              title={groupKey === DEFAULT_GROUP ? labels.stepsTitle || 'Types of Artifact' : humanize(groupKey)}
              hint={shapes
                ? 'Click a tile to filter papers. The Publication Timeline below uses the same colours and shapes.'
                : 'Click a tile to filter papers. The Publication Timeline below uses the same colours.'}
            />

            {config.features?.landscape !== false && (
              <section className="landscape-section">
                <div className="landscape-section__head">
                  <h2 className="detail-section__title">{labels.landscapeTitle || 'Publication Timeline'}</h2>
                  <ShapesToggle />
                </div>
                {labels.landscapeDescription && <p className="graph-page__description">{labels.landscapeDescription}</p>}
                <LandscapeVisualization papers={papers} highlightIds={highlightIds} colorOf={landscapeColorOf} shapeOf={landscapeShapeOf} />
              </section>
            )}

          </div>

          <div className="papers-layout__sidebar">
            <div className="results-head">
              <p className="results-count">
                {sidebarPapers.length} {sidebarPapers.length === 1 ? labels.entrySingular || 'paper' : labels.entryPlural || 'papers'} listed
              </p>
              <div className="results-head__actions">
                {config.features?.compare !== false && (
                  <button
                    type="button"
                    className={`btn btn--sm ${compareMode ? 'btn--primary' : 'btn--secondary'}`}
                    onClick={() => {
                      setCompareMode((v) => !v);
                      setCompareIds([]);
                    }}
                    title="Select papers in the list to compare them"
                  >
                    {compareMode ? 'Cancel compare' : 'Compare'}
                  </button>
                )}
                {papers.some((p) => p._userAdded) && (
                  <button type="button" className="btn btn--sm btn--secondary" onClick={() => setShowPropose(true)}>
                    Propose your papers ({papers.filter((p) => p._userAdded).length})
                  </button>
                )}
                <button type="button" className="btn btn--sm btn--primary" onClick={() => setShowAddPaper(true)}>
                  + Add Paper
                </button>
              </div>
            </div>
            {compareMode && <p className="results-hint">Click papers to select them for comparison.</p>}

            {sidebarPapers.length === 0 ? (
              <div className="empty-state">
                <p>No papers match the current filters.</p>
              </div>
            ) : (
              <div className="paper-list">
                {sidebarPapers.map((paper) => (
                  <PaperCard
                    key={paper._id}
                    paper={paper}
                    artifactColors={artifactColors}
                    compareMode={compareMode}
                    selected={compareIds.includes(paper._id)}
                    onToggleCompare={toggleCompare}
                  />
                ))}
              </div>
            )}
          </div>
        </div>
      </main>

      {compareMode && compareIds.length > 0 && (
        <div className="compare-bar">
          <span className="compare-bar__count">{compareIds.length} selected</span>
          <button className="btn btn--ghost btn--sm" onClick={() => setCompareIds([])}>Clear</button>
          <button
            className="btn btn--primary btn--sm"
            disabled={compareIds.length < 2}
            onClick={() => navigate(`/compare?ids=${compareIds.join(',')}`)}
          >
            Compare →
          </button>
        </div>
      )}

      {showAddPaper && (
        <AddPaperModal config={config} papers={papers} onClose={() => setShowAddPaper(false)} onAdded={handlePaperAdded} />
      )}
      {showPropose && (
        <ProposePapersModal papers={papers} onClose={() => setShowPropose(false)} onProposed={handlePaperAdded} />
      )}
    </div>
  );
}
