import { useEffect, useMemo, useRef, useState } from 'react';
import { humanize } from '@/lib/humanize';
import { FILTER_FACETS, FILTER_GROUPS, activeFilterCount, facetOptions, matchesFilters } from '@/lib/facets';
import { useFilters } from '@/lib/filterState';
import { makeShapeFor } from '@/lib/colors';
import { ShapeIcon, useShapes } from '@/lib/shapes';

// One dropdown per core facet (Year, Conference, Track, Type of Artifact), then one per
// labelled group (Research, Method & Evaluation, Threats to Reliability & Validity).
const BUTTONS = FILTER_GROUPS.flatMap((g) =>
  g.label ? [{ id: g.id, label: g.label, facets: g.facets }] : g.facets.map((f) => ({ id: f.key, label: f.label, facets: [f] }))
);

const valueLabel = (key, v) => (key === 'year' || key === 'conference' ? v : humanize(v));

export default function FilterBar({
  papers, config, search, searchActive = false, onClearSearch, entryLabel = 'papers', orientation = 'horizontal',
}) {
  const { filters, toggle, clear } = useFilters();
  const active = activeFilterCount(filters);
  const vertical = orientation === 'vertical';
  const [openId, setOpenId] = useState(null);
  // Vertical panel: several sections can be open at once. Year, Conference, Track
  // and Type of Artifact start open, plus any group that already has a filter set.
  const [openSections, setOpenSections] = useState(() => new Set(
    BUTTONS.filter((b) => b.facets.length === 1 || b.facets.some((f) => filters[f.key]?.length)).map((b) => b.id)
  ));
  const toggleSection = (id) => setOpenSections((prev) => {
    const next = new Set(prev);
    if (next.has(id)) next.delete(id); else next.add(id);
    return next;
  });
  const [alignRight, setAlignRight] = useState(false);
  const rootRef = useRef(null);
  const buttonRefs = useRef({});

  const colorOf = useMemo(() => {
    const maps = {
      type_of_artifact: Object.fromEntries((config?.typesOfArtifact || []).map((t) => [t.id, t.color])),
      type_of_inquiry: Object.fromEntries((config?.typesOfInquiry || []).map((t) => [t.id, t.color])),
    };
    return (key, value) => maps[key]?.[value] || null;
  }, [config]);

  const { shapes } = useShapes();
  const shapeOf = useMemo(() => (shapes ? makeShapeFor(config || {}, papers) : null), [shapes, config, papers]);

  const matching = useMemo(() => papers.filter((p) => matchesFilters(p, filters)).length, [papers, filters]);

  useEffect(() => {
    if (!openId) return undefined;
    const onPointerDown = (e) => {
      if (!rootRef.current?.contains(e.target)) setOpenId(null);
    };
    const onKeyDown = (e) => {
      if (e.key !== 'Escape') return;
      buttonRefs.current[openId]?.focus();
      setOpenId(null);
    };
    document.addEventListener('pointerdown', onPointerDown);
    document.addEventListener('keydown', onKeyDown);
    return () => {
      document.removeEventListener('pointerdown', onPointerDown);
      document.removeEventListener('keydown', onKeyDown);
    };
  }, [openId]);

  const toggleOpen = (id) => {
    if (openId === id) { setOpenId(null); return; }
    const rect = buttonRefs.current[id]?.getBoundingClientRect();
    setAlignRight(Boolean(rect && rect.left > window.innerWidth / 2));
    setOpenId(id);
  };

  const clearAll = () => {
    clear();
    onClearSearch?.();
  };

  const renderFacet = (facet, showLabel) => {
    const options = facetOptions(papers, facet, filters);
    if (!options.length) return null;
    const selected = filters[facet.key] || [];
    return (
      <div className="fs-facet" key={facet.key}>
        {showLabel && <span className="fs-facet__label">{facet.label}</span>}
        <div className="fs-facet__chips">
          {options.map(({ value, count }) => {
            const isOn = selected.includes(value);
            const empty = count === 0 && !isOn;
            const color = colorOf(facet.key, value);
            return (
              <button
                key={value}
                type="button"
                className={`filter-chip fs-chip ${isOn ? 'filter-chip--active' : ''} ${empty ? 'fs-chip--empty' : ''}`}
                onClick={() => toggle(facet.key, value)}
                aria-pressed={isOn}
                disabled={empty}
                title={empty ? 'No papers with the current filters' : undefined}
              >
                {color && shapeOf && shapeOf(facet.key, value) ? (
                  <span className="fs-chip__dot fs-chip__dot--shape" aria-hidden="true">
                    <ShapeIcon shape={shapeOf(facet.key, value)} color={color} size={10} />
                  </span>
                ) : (
                  color && <span className="fs-chip__dot" style={{ background: color }} aria-hidden="true" />
                )}
                {valueLabel(facet.key, value)}
                <span className="filter-chip__count">{count}</span>
              </button>
            );
          })}
        </div>
      </div>
    );
  };

  const activeChips = active > 0 && (
    <div className="fb-active" aria-label="Active filters">
      {FILTER_FACETS.flatMap((f) => (filters[f.key] || []).map((v) => (
        <button key={`${f.key}:${v}`} type="button" className="filter-chip filter-chip--active fs-chip"
          onClick={() => toggle(f.key, v)} title={`Remove filter: ${f.label}`}>
          <span className="fb-active__facet">{f.label}:</span> {valueLabel(f.key, v)} <span aria-hidden="true">×</span>
        </button>
      )))}
    </div>
  );

  if (vertical) {
    return (
      <aside className="filter-panel" aria-label="Filters">
        <div className="fp-head">
          <span className="fp-head__title">Filters{active > 0 && <span className="fs-badge">{active}</span>}</span>
          <span className="fb-count">
            {active > 0 ? <><strong>{matching}</strong> of {papers.length}</> : papers.length} {entryLabel}
          </span>
        </div>
        {search && <div className="fp-search">{search}</div>}
        {(active > 0 || searchActive) && (
          <div className="fp-clear">
            <button type="button" className="btn btn--ghost btn--sm" onClick={clearAll}>Clear all</button>
          </div>
        )}
        {activeChips}
        {BUTTONS.map((b) => {
          const count = b.facets.reduce((s, f) => s + (filters[f.key]?.length || 0), 0);
          const isOpen = openSections.has(b.id);
          return (
            <div className="fp-section" key={b.id}>
              <button type="button" className="fp-section__head" aria-expanded={isOpen}
                aria-controls={`fp-sec-${b.id}`} onClick={() => toggleSection(b.id)}>
                <span className="fb-btn__chevron" aria-hidden="true" />
                {b.label}
                {count > 0 && <span className="fs-badge">{count}</span>}
              </button>
              {isOpen && (
                <div id={`fp-sec-${b.id}`} className="fp-section__body">
                  {b.facets.map((f) => renderFacet(f, b.facets.length > 1))}
                </div>
              )}
            </div>
          );
        })}
      </aside>
    );
  }

  return (
    <section className="filter-bar" ref={rootRef} aria-label="Filters">
      <div className="fb-row">
        {search && <div className="fb-search">{search}</div>}

        <div className="fb-buttons">
          <span className="fb-label" aria-hidden="true">Filter</span>
          {BUTTONS.map((b) => {
            const count = b.facets.reduce((s, f) => s + (filters[f.key]?.length || 0), 0);
            const isOpen = openId === b.id;
            return (
              <div className="fb-item" key={b.id}>
                <button
                  type="button"
                  ref={(el) => { buttonRefs.current[b.id] = el; }}
                  className={`fb-btn ${isOpen ? 'fb-btn--open' : ''} ${count ? 'fb-btn--active' : ''}`}
                  aria-expanded={isOpen}
                  aria-controls={`fb-pop-${b.id}`}
                  onClick={() => toggleOpen(b.id)}
                >
                  {b.label}
                  {count > 0 && <span className="fs-badge">{count}</span>}
                  <span className="fb-btn__chevron" aria-hidden="true" />
                </button>
                {isOpen && (
                  <div id={`fb-pop-${b.id}`} className={`fb-pop ${alignRight ? 'fb-pop--right' : ''}`}
                    role="group" aria-label={`${b.label} filters`}>
                    {b.facets.map((f) => renderFacet(f, b.facets.length > 1))}
                  </div>
                )}
              </div>
            );
          })}
        </div>

        <div className="fb-summary">
          <span className="fb-count">
            {active > 0 ? <><strong>{matching}</strong> of {papers.length}</> : papers.length} {entryLabel}
          </span>
          {(active > 0 || searchActive) && (
            <button type="button" className="btn btn--ghost btn--sm" onClick={clearAll}>Clear all</button>
          )}
        </div>
      </div>

      {activeChips}
    </section>
  );
}
