const CATEGORICAL = new Set(['single', 'multi', 'boolean', 'composite']);
const CATEGORY_LIKE = new Set([...CATEGORICAL, 'text']);
const GROUPABLE = new Set(['single', 'multi', 'composite', 'text']);
const MAX_GROUP_VALUES = 12;
const STORAGE_KEY = 'ariadne-lit:uploaded-schema';

export const KIND_LABELS = {
  single: 'Single choice',
  multi: 'Multiple choice',
  boolean: 'Yes / no',
  composite: 'Combined',
  number: 'Number',
  list: 'Free list',
  text: 'Text',
};

export const ROLES = [
  { key: 'year', label: 'Year', description: 'Fixed: places papers on the Publication Timeline and is the time axis of Trends.', fits: (a) => a.kind === 'number' },
  { key: 'keywords', label: 'Keywords', description: 'Fixed: connects papers in the Paper Metagraph.', fits: (a) => a.kind === 'list' || a.kind === 'multi' },
];

export const USES = [
  { key: 'overview.tiles', view: 'Overview', label: 'Tiles', fits: (a) => CATEGORY_LIKE.has(a.kind) },
  { key: 'overview.defaultTile', view: 'Overview', label: 'Default tiles', single: true, fits: (a) => CATEGORY_LIKE.has(a.kind) },
  { key: 'overview.timelineRows', view: 'Overview', label: 'Timeline rows', single: true, fits: (a) => GROUPABLE.has(a.kind) },
  { key: 'metagraph.groups', view: 'Paper Metagraph', label: 'Groups', fits: (a) => GROUPABLE.has(a.kind) },
  { key: 'patterns.rowsColumns', view: 'Patterns & Trends', label: 'Rows / Columns', fits: (a) => CATEGORY_LIKE.has(a.kind) || a.kind === 'number' },
  { key: 'patterns.trends', view: 'Patterns & Trends', label: 'Trends', fits: (a) => CATEGORY_LIKE.has(a.kind) },
  { key: 'about.dimension', view: 'About', label: 'Coding scheme', fits: (a) => CATEGORY_LIKE.has(a.kind) },
  { key: 'filters', view: 'All views', label: 'Filter', fits: (a) => CATEGORY_LIKE.has(a.kind) || a.kind === 'number' },
];

function kindOf(node) {
  if (node['x-ariadne'] && node.type === 'object') return 'composite';
  if (node.type === 'boolean') return 'boolean';
  if (node.type === 'integer' || node.type === 'number') return 'number';
  if (node.type === 'array') {
    const items = node.items || {};
    if (Array.isArray(items.enum)) return node.maxItems === 1 ? 'single' : 'multi';
    if (items.type === 'string') return 'list';
    return null;
  }
  if (node.type === 'string' || node.enum) return Array.isArray(node.enum) ? 'single' : 'text';
  return null;
}

export function extractAttributes(schema) {
  const attributes = [];
  const walk = (node, path) => {
    if (!node || typeof node !== 'object') return;
    const isObject = node.type === 'object' || node.properties;
    if (isObject && (!node['x-ariadne'] || !path.length)) {
      Object.entries(node.properties || {}).forEach(([name, child]) => walk(child, [...path, name]));
      return;
    }
    if (node.type === 'array' && node.items && (node.items.type === 'object' || node.items.properties)) {
      Object.entries(node.items.properties || {}).forEach(([name, child]) => walk(child, [...path.slice(0, -1), `${path[path.length - 1]}[]`, name]));
      return;
    }
    const kind = kindOf(node);
    if (!kind || !path.length) return;
    attributes.push({
      path: path.join('.'),
      name: path[path.length - 1].replace(/\[\]$/, ''),
      kind,
      values: node.enum || node.items?.enum || null,
      description: node.description || '',
      annotation: node['x-ariadne'] || null,
    });
  };
  walk(schema, []);
  return attributes;
}

export function validateSchema(schema) {
  if (!schema || typeof schema !== 'object' || Array.isArray(schema)) return 'The file is not a JSON object.';
  if (!schema.properties || typeof schema.properties !== 'object') return 'The schema has no "properties", so it describes no attributes.';
  if (!extractAttributes(schema).length) return 'No attributes with a usable type (text, number, yes/no, choice or list) were found.';
  return null;
}

export function mappingFromAnnotations(attributes) {
  const roles = {};
  const uses = {};
  attributes.forEach((a) => {
    if (a.annotation?.role) roles[a.annotation.role] = a.path;
    uses[a.path] = new Set(a.annotation?.uses || []);
  });
  return { roles, uses };
}

export function suggestMapping(attributes) {
  if (attributes.some((a) => a.annotation)) return mappingFromAnnotations(attributes);
  const roles = {};
  const year = attributes.find((a) => a.kind === 'number' && /year/i.test(a.name)) || attributes.find((a) => a.kind === 'number');
  const keywords = attributes.find((a) => (a.kind === 'list' || a.kind === 'multi') && /keyword|tag/i.test(a.name))
    || attributes.find((a) => a.kind === 'list');
  if (year) roles.year = year.path;
  if (keywords) roles.keywords = keywords.path;
  const uses = {};
  let defaultTile = false;
  attributes.forEach((a) => {
    const set = new Set();
    if (a.path === roles.keywords) {
      uses[a.path] = set;
      return;
    }
    if (CATEGORICAL.has(a.kind)) {
      ['filters', 'overview.tiles', 'patterns.rowsColumns', 'patterns.trends', 'about.dimension'].forEach((u) => set.add(u));
      if (!defaultTile && a.kind !== 'boolean') {
        set.add('overview.defaultTile');
        defaultTile = true;
      }
      if (a.kind === 'single' && (a.values?.length || 0) <= MAX_GROUP_VALUES) set.add('metagraph.groups');
    }
    if (a.kind === 'number') ['filters', 'patterns.rowsColumns'].forEach((u) => set.add(u));
    uses[a.path] = set;
  });
  return { roles, uses };
}

export function toggleUse(mapping, path, useKey) {
  const use = USES.find((u) => u.key === useKey);
  const uses = Object.fromEntries(Object.entries(mapping.uses).map(([p, set]) => [p, new Set(set)]));
  const on = uses[path]?.has(useKey);
  if (use?.single) Object.values(uses).forEach((set) => set.delete(useKey));
  if (!uses[path]) uses[path] = new Set();
  if (!on) uses[path].add(useKey);
  else uses[path].delete(useKey);
  return { ...mapping, uses };
}

function nodeAt(schema, path) {
  let node = schema;
  for (const raw of path.split('.')) {
    const isArray = raw.endsWith('[]');
    const name = raw.replace(/\[\]$/, '');
    node = node?.properties?.[name];
    if (isArray) node = node?.items;
  }
  return node;
}

export function applyMapping(schema, attributes, mapping, meta) {
  const filled = JSON.parse(JSON.stringify(schema));
  attributes.forEach((a) => {
    const node = nodeAt(filled, a.path);
    if (!node) return;
    const role = Object.entries(mapping.roles).find(([, p]) => p === a.path)?.[0];
    const uses = [...(mapping.uses[a.path] || [])];
    const block = { ...(role ? { role } : {}), ...(uses.length ? { uses } : {}) };
    if (Object.keys(block).length) node['x-ariadne'] = block;
    else delete node['x-ariadne'];
  });
  if (meta) filled['x-ariadne'] = meta;
  return filled;
}

export function loadUploadedSchema() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    const stored = JSON.parse(raw);
    return { ...stored, mapping: { roles: stored.mapping.roles, uses: Object.fromEntries(Object.entries(stored.mapping.uses).map(([p, u]) => [p, new Set(u)])) } };
  } catch {
    return null;
  }
}

export function saveUploadedSchema(state) {
  try {
    if (!state) {
      localStorage.removeItem(STORAGE_KEY);
      return;
    }
    const uses = Object.fromEntries(Object.entries(state.mapping.uses).map(([p, set]) => [p, [...set]]));
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ ...state, mapping: { roles: state.mapping.roles, uses } }));
  } catch {
    return;
  }
}
