export function AboutToggle({ open, onToggle, panelId }) {
  return (
    <button type="button" className={`ax-about-toggle ${open ? 'is-open' : ''}`} onClick={onToggle}
      aria-expanded={open} aria-controls={panelId}>
      <span className="ax-about-toggle__icon" aria-hidden="true">?</span>
      How to read this
    </button>
  );
}

export function AboutPanel({ open, id, children }) {
  if (!open) return null;
  return <div id={id} className="ax-about-panel">{children}</div>;
}
