import * as d3 from 'd3';
import { isAnonymized } from '@/lib/filters';
import { shapePath } from '@/lib/shapes';

const FALLBACK_COLOR = '#88c0d0';
const AXIS_FONT_SIZE = 12;

// Deterministic 0..1 value per paper and axis, so a dot keeps its place across
// re-renders (typing in search, changing filters, resizing) instead of jumping.
function stableRandom(key) {
  let h = 2166136261;
  for (let i = 0; i < key.length; i += 1) {
    h ^= key.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return ((h >>> 0) % 100000) / 100000;
}

/**
 * Draws the papers in highlightIds (null = all). The year and track axes
 * cover only those papers; tracks keep their order across all papers.
 * setColors(colorOf) recolours dots in place.
 */
export function createLandscape(container, papers, { colorOf, shapeOf = null, highlightIds = null, onPaperClick } = {}) {
  const width = container.clientWidth || 900;

  const trackCounts = new Map();
  papers.forEach((p) => {
    const track = p.metadata?.track;
    if (track) trackCounts.set(track, (trackCounts.get(track) || 0) + 1);
  });
  const shown = (highlightIds ? papers.filter((p) => highlightIds.has(p._id)) : papers)
    .filter((p) => p.metadata?.year && p.metadata?.track);

  if (shown.length === 0) {
    const empty = d3.select(container).append('p').attr('class', 'landscape-empty').text('No papers match the current filters.');
    return { setColors: () => {}, destroy: () => empty.remove() };
  }

  const yearExtent = d3.extent(shown, (p) => p.metadata.year);
  const yearDomain = [yearExtent[0] - 0.5, yearExtent[1] + 0.5];
  const shownTracks = new Set(shown.map((p) => p.metadata.track));
  const tracks = [...trackCounts.keys()]
    .sort((a, b) => b.localeCompare(a))
    .filter((track) => shownTracks.has(track));

  const svg = d3.select(container).append('svg');

  const probe = svg.append('text').attr('font-size', AXIS_FONT_SIZE).attr('visibility', 'hidden');
  const labelWidth = tracks.reduce((max, t) => Math.max(max, probe.text(t).node().getComputedTextLength()), 0);
  probe.remove();

  const margin = { top: 16, right: 16, bottom: 36, left: Math.ceil(labelWidth) + 18 };

  const viewportCap = Math.max(260, (window.innerHeight || 800) * 0.5);
  const height = Math.round(Math.min(
    Math.max(width * 0.32, 260, margin.top + margin.bottom + tracks.length * 48),
    viewportCap,
  ));

  const x = d3
    .scaleLinear()
    .domain(yearDomain)
    .range([margin.left, width - margin.right]);

  const y = d3
    .scaleBand()
    .domain(tracks)
    .range([height - margin.bottom, margin.top])
    .paddingOuter(0.5);

  svg
    .attr('width', width)
    .attr('height', height)
    .attr('viewBox', [0, 0, width, height]);

  const yearTicks = d3.range(Math.ceil(yearDomain[0]), Math.floor(yearDomain[1]) + 1);

  svg
    .append('g')
    .attr('transform', `translate(0,${height - margin.bottom})`)
    .call(d3.axisBottom(x).tickFormat(d3.format('d')).tickValues(yearTicks.length > 12 ? x.ticks(10).filter(Number.isInteger) : yearTicks))
    .call((g) => g.selectAll('text').attr('fill', 'var(--text-muted)').attr('font-size', AXIS_FONT_SIZE))
    .call((g) => g.selectAll('line,path').attr('stroke', 'var(--border)'));

  svg
    .append('g')
    .attr('transform', `translate(${margin.left},0)`)
    .call(d3.axisLeft(y).tickSize(0).tickPadding(10))
    .call((g) => g.selectAll('text').attr('fill', 'var(--text-muted)').attr('font-size', AXIS_FONT_SIZE))
    .call((g) => g.selectAll('line,path').attr('stroke', 'var(--border)'));

  const jitterX = (id) => (stableRandom(`${id}:x`) - 0.5) * 0.5;
  const jitterY = (id) => (stableRandom(`${id}:y`) - 0.5) * y.bandwidth() * 0.7;
  const colorFor = (fn, p) => (fn && fn(p)) || FALLBACK_COLOR;

  const points = shown
    .map((p) => {
      const key = String(p._id ?? p.metadata.title ?? '');
      return {
        paper: p,
        x: p.metadata.year + jitterX(key) * 0.7,
        y: y(p.metadata.track) + y.bandwidth() / 2 + jitterY(key),
        color: colorFor(colorOf, p),
        shape: (shapeOf && shapeOf(p)) || 'circle',
        radius: 4 + Math.min(p.contribution?.artifacts?.length || 1, 4) * 1.5,
        anonymized: isAnonymized(p),
        userAdded: Boolean(p._userAdded),
      };
    });

  const tooltip = d3
    .select(container)
    .append('div')
    .attr('class', 'landscape-tooltip')
    .style('opacity', 0);

  const pointsLayer = svg.append('g');
  const ringsLayer = pointsLayer.append('g');
  const dotsLayer = pointsLayer.append('g');
  const keyOf = (d) => d.paper._id;
  let circles = dotsLayer.selectAll('path.landscape-point');

  const draw = () => {
    const visible = points;

    // Dashed accent ring behind papers added by the visitor, same treatment
    // as the relationship graph.
    ringsLayer
      .selectAll('circle.user-added-ring')
      .data(visible.filter((d) => d.userAdded), keyOf)
      .join((enter) => enter
        .append('circle')
        .attr('class', 'user-added-ring')
        .attr('cx', (d) => x(d.x))
        .attr('cy', (d) => d.y)
        .attr('r', (d) => d.radius + 4)
        .attr('fill', 'none')
        .attr('stroke', 'var(--accent)')
        .attr('stroke-width', 1.5)
        .attr('stroke-dasharray', '3,2')
        .style('pointer-events', 'none'));

    circles = dotsLayer
      .selectAll('path.landscape-point')
      .data(visible, keyOf)
      .join((enter) => enter
        .append('path')
        .attr('class', 'landscape-point')
        .attr('transform', (d) => `translate(${x(d.x)},${d.y})`)
        .attr('d', (d) => shapePath(d.shape, d.radius))
        .attr('fill-opacity', (d) => (d.anonymized ? 0.28 : 0.75))
        .attr('stroke', (d) => (d.anonymized ? 'var(--bg)' : 'var(--text)'))
        .attr('stroke-width', 1)
        .style('cursor', 'pointer')
        .on('mouseenter', (event, d) => {
          if (d.anonymized) return;
          const addedTag = d.userAdded ? ' <span style="color:var(--accent-text)">· Added by you</span>' : '';
          tooltip
            .style('opacity', 1)
            .html(`<strong>${d.paper.metadata.title}</strong>${addedTag}<br/>${d.paper.metadata.year} · ${d.paper.metadata.track}`);
        })
        .on('mousemove', (event) => {
          const [mx, my] = d3.pointer(event, container);
          const tooltipWidth = tooltip.node().offsetWidth;
          const overflowsRight = mx + 12 + tooltipWidth > container.clientWidth;
          const left = overflowsRight ? mx - 12 - tooltipWidth : mx + 12;
          tooltip.style('left', `${left}px`).style('top', `${my + 12}px`);
        })
        .on('mouseleave', () => tooltip.style('opacity', 0))
        .on('click', (event, d) => {
          if (onPaperClick) onPaperClick(d.paper._id);
        }))
      .attr('fill', (d) => d.color);
    tooltip.style('opacity', 0);
  };
  draw();

  return {
    setColors: (fn) => {
      points.forEach((d) => { d.color = colorFor(fn, d.paper); });
      circles.attr('fill', (d) => d.color);
    },
    destroy: () => {
      circles.interrupt();
      tooltip.remove();
      svg.remove();
    },
  };
}
