import { markUserPapersProposed } from './data';

// The public Pages mirror, not the private source repo — anonymous visitors
// have no access to the private one, so an issue link there would just 404
// for them. Someone with access to both repos can port issues filed here
// over to the source repo's coding spreadsheet.
const REPO = 'andreamalhera/nfdixcs_research_artifact_graph-pages';

/** Pre-fills a "New Issue" form on the source repo with the submitted
 * paper's data, so a maintainer can review it and fold it into the real
 * dataset (methods.json / the coding spreadsheet) later — there's no
 * backend here to write it in directly. */
export function buildIssueUrl(record) {
  const { metadata, contribution } = record;
  const artifact = contribution.artifacts[0];
  const components = contribution.research_components || {};
  const body = [
    'A visitor submitted this paper through the "Add Paper" flow. Please review and, if it checks out, fold it into the coding spreadsheet / `methods.json`.',
    '',
    `**Title**: ${metadata.title}`,
    `**Authors**: ${metadata.authors.join(', ') || '_(none given)_'}`,
    `**Year**: ${metadata.year || '_(none given)_'}`,
    `**Conference**: ${[metadata.conference_name, metadata.conference_abbreviation && `(${metadata.conference_abbreviation})`].filter(Boolean).join(' ') || '_(none given)_'}`,
    `**Track**: ${metadata.track || '_(none given)_'}`,
    `**DOI/URL**: ${metadata.doi_or_url || '_(none given)_'}`,
    `**Keywords**: ${contribution.keywords.join(', ') || '_(none given)_'}`,
    `**Type of Inquiry**: ${contribution.focus_intent.type_of_inquiry.join(', ') || '_(none given)_'}`,
    `**Type of Artifact**: ${artifact.type_of_artifact.join(', ') || '_(none given)_'}`,
    `**Type of Theory**: ${(components.type_of_theory || []).join(', ') || '_(none given)_'}`,
    `**Emphasis**: ${(components.emphasis || []).join(', ') || '_(none given)_'}`,
    `**Contains formal concepts**: ${components.formal_concepts ? 'Yes' : 'No'}`,
    `**Contains an algorithm**: ${components.algorithms ? 'Yes' : 'No'}`,
    `**Contains a statistical hypothesis**: ${components.hypothesis ? 'Yes' : 'No'}`,
    ...(components.hypothesis
      ? [
        `**Independent variables**: ${components.independent_variables || '_(none given)_'}`,
        `**Dependent variables**: ${components.dependent_variables || '_(none given)_'}`,
      ]
      : []),
    `**Research Method**: ${artifact.research_method.methods.join(', ') || '_(none given)_'}`,
    `**Evaluation Method**: ${artifact.evaluation_method.join(', ') || '_(none given)_'}`,
    `**Data Type**: ${artifact.data_collection.data_type.join(', ') || '_(none given)_'}`,
    `**Threats to Validity**: ${artifact.threats_to_validity.join(', ') || '_(none given)_'}`,
    `**Implementation exists**: ${artifact.implementation.existence ? 'Yes' : 'No'}`,
    `**Publicly available**: ${artifact.implementation.availability ? 'Yes' : 'No'}`,
    '',
    '<details><summary>Raw record</summary>',
    '',
    '```json',
    JSON.stringify(
      { metadata, contribution },
      null,
      2
    ),
    '```',
    '</details>',
  ].join('\n');

  const params = new URLSearchParams({
    title: `New paper submission: ${metadata.title || '(untitled)'}`,
    body,
    labels: 'paper-submission',
  });
  return `https://github.com/${REPO}/issues/new?${params.toString()}`;
}

export function proposalFileName() {
  return `ariadne-lit-papers-${new Date().toISOString().slice(0, 10)}.json`;
}

export function downloadProposal(papers, fileName) {
  const records = papers.map(({ metadata, contribution }) => ({ metadata, contribution }));
  const blob = new Blob([`${JSON.stringify(records, null, 2)}\n`], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = fileName;
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  return records;
}

export function buildBatchIssueUrl(papers, records, fileName) {
  const list = papers.map((p, i) => {
    const m = p.metadata;
    const venue = [m.conference_abbreviation, m.year].filter(Boolean).join(' ');
    return `${i + 1}. ${m.title || '(untitled)'}${venue ? ` (${venue})` : ''}${m.doi_or_url ? ` ${m.doi_or_url}` : ''}`;
  });
  const intro = [
    `> **Before submitting:** attach the downloaded file \`${fileName}\` with the coded papers by dragging it into this box, then delete this line.`,
    '',
    `A visitor submitted these ${papers.length} papers through the "Add Paper" flow. Please review them and, if they check out, fold them into the coding spreadsheet / \`methods.json\`.`,
    '',
    ...list,
  ];
  const withRecords = [
    ...intro,
    '',
    '<details><summary>Raw records</summary>',
    '',
    '```json',
    JSON.stringify(records, null, 2),
    '```',
    '</details>',
  ].join('\n');
  const body = encodeURIComponent(withRecords).length < 6000 ? withRecords : intro.join('\n');
  const params = new URLSearchParams({
    title: `New paper submissions: ${papers.length} papers`,
    body,
    labels: 'paper-submission',
  });
  return `https://github.com/${REPO}/issues/new?${params.toString()}`;
}

export async function proposePapers(papers) {
  if (papers.length === 0) return;
  if (papers.length === 1) {
    window.open(buildIssueUrl(papers[0]), '_blank', 'noopener,noreferrer');
  } else {
    const fileName = proposalFileName();
    const records = downloadProposal(papers, fileName);
    window.open(buildBatchIssueUrl(papers, records, fileName), '_blank', 'noopener,noreferrer');
  }
  await markUserPapersProposed(papers.map((p) => p._userKey));
}
