import { DIMENSIONS, MISSING, buildUnits, unitValues } from './analysis';
import { shapeAt } from './shapes';

// --- perceptual distance between palette colours (CIELAB, ΔE76) -----------
function hexToLab(hex) {
  const m = /^#?([0-9a-f]{6})$/i.exec(hex || '');
  if (!m) return null;
  const n = parseInt(m[1], 16);
  const lin = (c) => { const s = c / 255; return s <= 0.04045 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4; };
  const [r, g, b] = [lin(n >> 16), lin((n >> 8) & 255), lin(n & 255)];
  const f = (t) => (t > 216 / 24389 ? Math.cbrt(t) : (24389 / 27 * t + 16) / 116);
  const fx = f((0.4124 * r + 0.3576 * g + 0.1805 * b) / 0.95047);
  const fy = f(0.2126 * r + 0.7152 * g + 0.0722 * b);
  const fz = f((0.0193 * r + 0.1192 * g + 0.9505 * b) / 1.08883);
  return [116 * fy - 16, 500 * (fx - fy), 200 * (fy - fz)];
}

const deltaE = (a, b) => Math.hypot(a[0] - b[0], a[1] - b[1], a[2] - b[2]);

/**
 * Picks n colours from the palette that are as different from each other as
 * possible: start with the first palette colour, then repeatedly add the one
 * farthest (in perceived colour) from everything picked so far.
 */
function contrastingSubset(palette, n) {
  const pool = [...new Set(palette)].map((hex) => ({ hex, lab: hexToLab(hex) })).filter((c) => c.lab);
  if (n >= pool.length) return pool.map((c) => c.hex);
  const picked = [pool.shift()];
  while (picked.length < n) {
    let best = 0;
    let bestDist = -1;
    pool.forEach((c, i) => {
      const d = Math.min(...picked.map((p) => deltaE(p.lab, c.lab)));
      if (d > bestDist) { bestDist = d; best = i; }
    });
    picked.push(pool.splice(best, 1)[0]);
  }
  return picked.map((c) => c.hex);
}

/**
 * Returns colorFor(dimKey, value). Type of Artifact and Type of Inquiry use
 * the colours from site.config.json. Every other dimension takes its colours
 * from that same palette, values ordered by frequency (most common first), so
 * a value keeps its colour wherever it is shown. A dimension with fewer values
 * than Type of Artifact gets the most mutually distinct palette colours; one
 * with as many or more cycles through the palette.
 */
function valueOrders(config, papers) {
  const orders = {
    type_of_artifact: (config.typesOfArtifact || []).map((t) => t.id),
    type_of_inquiry: (config.typesOfInquiry || []).map((t) => t.id),
  };
  if (!papers) return orders;
  const byLevel = { artifact: buildUnits(papers, 'artifact'), paper: buildUnits(papers, 'paper') };
  DIMENSIONS.forEach((d) => {
    if (orders[d.key]) return;
    const counts = new Map();
    byLevel[d.level].forEach((u) =>
      unitValues(u, d).forEach((v) => v !== MISSING && counts.set(v, (counts.get(v) || 0) + 1))
    );
    orders[d.key] = [...counts.entries()]
      .sort((a, b) => (d.numeric ? Number(a[0]) - Number(b[0]) : b[1] - a[1] || a[0].localeCompare(b[0])))
      .map(([v]) => v);
  });
  return orders;
}

export function makeColorFor(config, papers) {
  const artifactTypes = config.typesOfArtifact || [];
  const inquiryTypes = config.typesOfInquiry || [];
  const maps = {
    type_of_artifact: Object.fromEntries(artifactTypes.map((t) => [t.id, t.color])),
    type_of_inquiry: Object.fromEntries(inquiryTypes.map((t) => [t.id, t.color])),
  };
  const palette = [...artifactTypes, ...inquiryTypes].map((t) => t.color);
  if (papers && palette.length) {
    Object.entries(valueOrders(config, papers)).forEach(([key, ordered]) => {
      if (maps[key]) return;
      const colors = ordered.length < artifactTypes.length ? contrastingSubset(palette, ordered.length) : palette;
      maps[key] = Object.fromEntries(ordered.map((v, i) => [v, colors[i % colors.length]]));
    });
  }
  return (dimKey, value) => maps[dimKey]?.[value] || null;
}

export function makeShapeFor(config, papers) {
  const maps = Object.fromEntries(
    Object.entries(valueOrders(config, papers)).map(([key, ordered]) => [key, Object.fromEntries(ordered.map((v, i) => [v, shapeAt(i)]))])
  );
  return (dimKey, value) => maps[dimKey]?.[value] || null;
}
