import { MISSING, buildUnits, getDimension, unitValues } from './analysis';

function dimValues(key) {
  const dim = getDimension(key);
  return (paper) => unitValues(buildUnits([paper], 'paper')[0], dim).filter((v) => v !== MISSING);
}

function contributionElements(paper) {
  const c = paper.contribution?.research_components || {};
  const out = [];
  if (c.formal_concepts) out.push('formal_concepts');
  if (c.algorithms) out.push('algorithms');
  if (c.hypothesis) out.push('hypothesis');
  return out;
}

export const FILTER_GROUPS = [
  {
    id: 'core',
    label: null,
    facets: [
      { key: 'year', label: 'Year', sortByValue: true, getValues: (p) => (p.metadata?.year ? [String(p.metadata.year)] : []) },
      { key: 'conference', label: 'Conference', getValues: (p) => (p.metadata?.conference_abbreviation ? [p.metadata.conference_abbreviation] : []) },
      { key: 'track', label: 'Track', getValues: (p) => (p.metadata?.track ? [p.metadata.track] : []) },
      { key: 'type_of_artifact', label: 'Type of Artifact', getValues: dimValues('type_of_artifact') },
    ],
  },
  {
    id: 'research',
    label: 'Research',
    facets: [
      { key: 'type_of_inquiry', label: 'Type of Inquiry', getValues: dimValues('type_of_inquiry') },
      { key: 'type_of_theory', label: 'Type of Theory', getValues: dimValues('type_of_theory') },
      { key: 'emphasis', label: 'Emphasis', getValues: dimValues('emphasis') },
      { key: 'contribution_elements', label: 'Contribution Elements', getValues: contributionElements },
    ],
  },
  {
    id: 'method',
    label: 'Method & Evaluation',
    facets: [
      { key: 'research_method', label: 'Research Method', getValues: dimValues('research_method') },
      { key: 'evaluation_method', label: 'Evaluation Method', getValues: dimValues('evaluation_method') },
    ],
  },
  {
    id: 'data',
    label: 'Threats to Reliability & Validity',
    facets: [
      { key: 'data_type', label: 'Data Type', getValues: dimValues('data_type') },
      { key: 'implementation', label: 'Implementation', getValues: dimValues('implementation') },
      { key: 'threats_to_validity', label: 'Threats to Validity', getValues: dimValues('threats_to_validity') },
    ],
  },
];

export const FILTER_FACETS = FILTER_GROUPS.flatMap((g) => g.facets);

const cache = new WeakMap();
export function facetValues(paper) {
  let v = cache.get(paper);
  if (!v) {
    v = Object.fromEntries(FILTER_FACETS.map((f) => [f.key, f.getValues(paper)]));
    cache.set(paper, v);
  }
  return v;
}

export function matchesFilters(paper, filters, exceptKey = null) {
  const values = facetValues(paper);
  return FILTER_FACETS.every((f) => {
    if (f.key === exceptKey) return true;
    const sel = filters[f.key];
    return !sel || sel.length === 0 || sel.some((v) => values[f.key].includes(v));
  });
}

export const activeFilterCount = (filters) =>
  Object.values(filters).reduce((s, v) => s + (v?.length || 0), 0);

export function facetOptions(papers, facet, filters) {
  const totals = new Map();
  const counts = new Map();
  papers.forEach((p) => {
    const vals = facetValues(p)[facet.key];
    const passes = matchesFilters(p, filters, facet.key);
    vals.forEach((v) => {
      totals.set(v, (totals.get(v) || 0) + 1);
      if (passes) counts.set(v, (counts.get(v) || 0) + 1);
    });
  });
  return [...totals.keys()]
    .map((value) => ({ value, count: counts.get(value) || 0, total: totals.get(value) }))
    .sort((a, b) => (facet.sortByValue ? a.value.localeCompare(b.value) : b.total - a.total || a.value.localeCompare(b.value)));
}
