function FloatingTip({ stageRef, anchor, contentKey, onMouseEnter, onMouseLeave, children }) {
  const tipRef = useRef(null);
  const [pos, setPos] = useState(null);
  const [tick, setTick] = useState(0);
  useEffect(() => {
    const bump = () => setTick((t) => t + 1);
    window.addEventListener('scroll', bump, true);
    window.addEventListener('resize', bump);
    return () => { window.removeEventListener('scroll', bump, true); window.removeEventListener('resize', bump); };
  }, []);
  useLayoutEffect(() => {
    const stage = stageRef.current;
    const tip = tipRef.current;
    if (!stage || !tip) return;
    const s = stage.getBoundingClientRect();
    const { width: tw, height: th } = tip.getBoundingClientRect();
    const m = 8;
    const above = s.top + anchor.top - th;
    const below = s.top + anchor.bottom;
    const fitsAbove = above >= m;
    const fitsBelow = below + th <= window.innerHeight - m;
    const useBelow = anchor.preferBelow ? fitsBelow || !fitsAbove : !fitsAbove && fitsBelow;
    const left = Math.min(Math.max(m, s.left + anchor.left - tw / 2), window.innerWidth - tw - m);
    setPos({ left, top: useBelow ? below : Math.max(m, above) });
  }, [anchor.left, anchor.top, anchor.bottom, anchor.preferBelow, contentKey, tick]);
  return createPortal(
    <div ref={tipRef} className="ax-tip ax-tip--interactive ax-tip--floating"
      style={pos ? { left: pos.left, top: pos.top } : { left: 0, top: 0, visibility: 'hidden' }}
      onMouseEnter={onMouseEnter} onMouseLeave={onMouseLeave}>
      {children}
    </div>,
    document.body
  );
}

function BubbleMatrix({
  tab, rows, cols, mode, value, unitWord, rowName, colName, rowColor, colColor, rowShape = () => null, onSelect,
  onTrend, canTrendRow, canTrendCol, assocOf, markSig, focus, onClearFocus,
}) {
  const [ref, width] = useWidth();
  const stageRef = useRef(null);
  const [hover, setHover] = useState(null);
  const [head, setHead] = useState(null);
  const cellColor = (r, c) => rowColor(r) || colColor(c) || null;

  // Tooltips hold links, so they close after a short delay: long enough to
  // move the pointer from a bubble or a name into its tooltip.
  const hideTimer = useRef(null);
  const switchTimer = useRef(null);
  useEffect(() => () => { clearTimeout(hideTimer.current); clearTimeout(switchTimer.current); }, []);
  const keepTip = () => { clearTimeout(hideTimer.current); clearTimeout(switchTimer.current); };
  const hideTip = () => {
    clearTimeout(hideTimer.current);
    hideTimer.current = setTimeout(() => { setHover(null); setHead(null); }, 250);
  };
  const switchTo = (fn) => {
    clearTimeout(hideTimer.current);
    clearTimeout(switchTimer.current);
    if (hover || head) switchTimer.current = setTimeout(fn, 160);
    else fn();
  };
  // After a pair is picked in "Significant Relations" the page scrolls, which
  // puts some other cell under the unmoved pointer. Hover is ignored until the
  // pointer really moves, so the picked cell keeps its highlight and tooltip.
  const hoverLock = useRef(false);
  useEffect(() => {
    if (!focus) return undefined;
    hoverLock.current = true;
    let start = null;
    const onMove = (e) => {
      if (!start) { start = { x: e.clientX, y: e.clientY }; return; }
      if (Math.abs(e.clientX - start.x) + Math.abs(e.clientY - start.y) > 4) {
        hoverLock.current = false;
        window.removeEventListener('mousemove', onMove);
      }
    };
    window.addEventListener('mousemove', onMove);
    return () => { window.removeEventListener('mousemove', onMove); hoverLock.current = false; };
  }, [focus]);

  const enterCell = (cell) => {
    if (hoverLock.current) return;
    if (hover && hover.ri === cell.ri && hover.ci === cell.ci) { keepTip(); return; }
    switchTo(() => { setHead(null); setHover(cell); onClearFocus?.(); });
  };
  const enterHead = (h) => {
    if (hoverLock.current) return;
    if (head && head.ri === h.ri && head.ci === h.ci && head.part === h.part) { keepTip(); return; }
    switchTo(() => { setHover(null); setHead(h); onClearFocus?.(); });
  };

  // A cell picked in "Significant Relations" stays highlighted (bands and
  // tooltip) until the pointer moves onto the matrix.
  const focusCell = focus && rows.includes(focus.r) && cols.includes(focus.c)
    ? { ...focus, ri: rows.indexOf(focus.r), ci: cols.indexOf(focus.c) } : null;
  const active = hover || (!head ? focusCell : null);
  const sigOf = (r, c) => {
    const a = markSig && assocOf ? assocOf(r, c) : null;
    return a && a.q < ALPHA ? a : null;
  };

  const charW = 6.6;
  const fontFamily = ref.current ? getComputedStyle(ref.current).fontFamily : 'sans-serif';
  const textW = (t, size = 12, weight = 600) => measureText(String(t), `${weight} ${size}px ${fontFamily}`);
  const headW = textW(`Total ${unitWord}`.toUpperCase(), 10, 400) * 1.03;
  const labelW = clamp(Math.max(headW + 14, ...rows.map((r) => textW(label(r)) + (rowColor(r) ? 26 : 14))) + 2, 72, 320);
  const longestCol = Math.max(...cols.map((c) => label(c).length));
  const rotate = longestCol * charW > 52;
  const top = rotate ? clamp(longestCol * charW * 0.6 + 22, 56, 140) : 34;
  const maxRowTotal = Math.max(1, ...rows.map((r) => tab.rowTotals.get(r) || 0));
  const marginW = Math.max(72 + textW(maxRowTotal, 12, 400), 16 + headW) + 4;
  const avail = Math.max(0, width - labelW - marginW - 8);
  const cw = clamp(avail / Math.max(1, cols.length), 46, rotate ? 76 : 96);
  const ch = clamp(cw * 0.85, 46, 58);
  const tailW = rotate
    ? Math.max(marginW, ...cols.map((c, ci) => textW(label(c)) * Math.cos(Math.PI / 5) - (cols.length - ci - 0.5) * cw + 2))
    : marginW;
  const W = labelW + cols.length * cw + tailW;
  const gridBottom = top + rows.length * ch;
  const colBarTop = gridBottom + 10;
  const colBarH = 32;
  const colNumY = colBarTop + colBarH + 16;
  const H = colNumY + 14;
  const rMax = Math.min(cw, ch) / 2 - 2.5;

  const max = Math.max(1e-9, ...rows.flatMap((r) => cols.map((c) => value(r, c))));
  const maxRowN = Math.max(1, ...rows.map((r) => tab.rowTotals.get(r) || 0));
  const maxColN = Math.max(1, ...cols.map((c) => tab.colTotals.get(c) || 0));
  const fmt = (v) => (mode === 'count' ? String(v) : `${Math.round(v * 100)}%`);

  const cx = (ci) => labelW + (ci + 0.5) * cw;
  const cy = (ri) => top + (ri + 0.5) * ch;
  const gridRight = labelW + cols.length * cw;
  const midX = labelW + (cols.length * cw) / 2;
  const midY = top + (rows.length * ch) / 2;

  const items = useMemo(() => {
    if (!width) return [];
    const out = [];
    rows.forEach((r, ri) => cols.forEach((c, ci) => {
      const v = value(r, c);
      if (v > 0) out.push({ key: `${r}|${c}`, tx: cx(ci), ty: cy(ri), r: Math.max(3.5, Math.sqrt(v / max) * rMax) });
    }));
    return out;
  }, [width, rows.join(), cols.join(), mode, tab, labelW, top, cw, ch, max, rMax]);

  const nodesRef = useRef(new Map());
  const elsRef = useRef(new Map());
  const simRef = useRef(null);
  const layoutSig = items.map((it) => `${it.key}:${Math.round(it.tx)},${Math.round(it.ty)},${Math.round(it.r)}`).join(';');

  useEffect(() => {
    if (!items.length) return undefined;
    const prev = nodesRef.current;
    const next = new Map();
    items.forEach((it) => {
      const n = prev.get(it.key) || {
        x: midX + (Math.random() - 0.5) * 60,
        y: midY + (Math.random() - 0.5) * 60,
      };
      Object.assign(n, it);
      next.set(it.key, n);
    });
    nodesRef.current = next;
    const nodes = [...next.values()];

    const place = () => nodes.forEach((n) => {
      const el = elsRef.current.get(n.key);
      if (el) el.setAttribute('transform', `translate(${n.x},${n.y})`);
    });

    simRef.current?.stop();

    if (window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) {
      nodes.forEach((n) => { n.x = n.tx; n.y = n.ty; });
      place();
      return undefined;
    }

    const sim = forceSimulation(nodes)
      .force('x', forceX((d) => d.tx).strength(0.12))
      .force('y', forceY((d) => d.ty).strength(0.12))
      .force('collide', forceCollide((d) => d.r + 1.5).strength(0.85).iterations(2))
      .velocityDecay(0.28)
      .alphaDecay(0.022)
      .on('tick', place)
      .on('end', () => {
        nodes.forEach((n) => { if (n.fx == null) { n.x = n.tx; n.y = n.ty; } });
        place();
      });
    simRef.current = sim;

    nodes.forEach((n) => {
      const el = elsRef.current.get(n.key);
      if (!el) return;
      d3select(el).call(
        d3drag()
          .subject(() => ({ x: n.x, y: n.y }))
          .on('start', (e) => {
            if (!e.active) sim.alphaTarget(0.3).restart();
            n.fx = n.x;
            n.fy = n.y;
            setHover(null);
          })
          .on('drag', (e) => {
            n.fx = e.x;
            n.fy = e.y;
          })
          .on('end', (e) => {
            n.fx = null;
            n.fy = null;
            if (!e.active) sim.alphaTarget(0).alpha(Math.max(sim.alpha(), 0.8)).restart();
          })
      );
    });

    return () => sim.stop();
  }, [layoutSig]);

  const bubbleRef = (key) => (el) => {
    if (!el) { elsRef.current.delete(key); return; }
    elsRef.current.set(key, el);
    const n = nodesRef.current.get(key);
    el.setAttribute('transform', `translate(${n ? n.x : midX},${n ? n.y : midY})`);
  };

  const rowAnchor = (ri) => ({ top: top + ri * ch, bottom: top + (ri + 1) * ch });

  const tip = active && (() => {
    const { r, c, ri, ci } = active;
    const k = tab.cell(r, c);
    const rn = tab.rowTotals.get(r) || 0;
    const cn = tab.colTotals.get(c) || 0;
    return { kind: 'cell', r, c, left: cx(ci), ...rowAnchor(ri), title: `${label(r)} × ${label(c)}`, k, rn, cn,
      assoc: assocOf ? assocOf(r, c) : null,
      rowShare: rn ? k / rn : 0, colShare: cn ? k / cn : 0 };
  })();

  const headTip = !active && head && (() => {
    if (head.ri !== undefined) {
      const r = rows[head.ri];
      if (r === undefined) return null;
      const left = head.part === 'total' ? gridRight + 48 : Math.max(90, labelW / 2);
      return { kind: 'row', value: r, left, ...rowAnchor(head.ri), title: `${rowName}: ${label(r)}`, n: tab.rowTotals.get(r) || 0 };
    }
    const c = cols[head.ci];
    if (c === undefined) return null;
    const anchor = head.part === 'total' ? { top: colBarTop, bottom: colBarTop + colBarH } : { top: 0, bottom: top, preferBelow: true };
    return { kind: 'col', value: c, left: cx(head.ci), ...anchor, title: `${colName}: ${label(c)}`, n: tab.colTotals.get(c) || 0 };
  })();

  return (
    <div className="ax-matrix" ref={ref}>
      {width > 0 && (
        <div className="ax-matrix__scroll">
          <div className="ax-matrix__stage" style={{ width: W, height: H }} ref={stageRef}>
            <svg width={W} height={H} className="ax-matrix__svg" role="img"
              aria-label={`Bubble matrix of ${rowName} by ${colName}; the table view lists every value`}>
              {active && (
                <>
                  <rect x={0} y={top + active.ri * ch} width={gridRight} height={ch} className="ax-matrix__band" rx="6" />
                  <rect x={labelW + active.ci * cw} y={top - 6} width={cw} height={rows.length * ch + 6} className="ax-matrix__band" rx="6" />
                </>
              )}
              {head?.ri !== undefined && (
                <rect x={0} y={top + head.ri * ch} width={W} height={ch} className="ax-matrix__band" rx="6" />
              )}
              {head?.ci !== undefined && (
                <rect x={labelW + head.ci * cw} y={0} width={cw} height={H} className="ax-matrix__band" rx="6" />
              )}

              {rows.map((r, ri) => (
                <line key={`g${r}`} x1={labelW - 8} x2={gridRight} y1={top + (ri + 1) * ch} y2={top + (ri + 1) * ch}
                  className="ax-matrix__rule" />
              ))}

              {cols.map((c, ci) => {
                const headProps = (part) => ({
                  className: 'ax-matrix__head',
                  role: 'button',
                  tabIndex: 0,
                  'aria-label': `See all papers with ${colName}: ${label(c)}`,
                  onClick: () => onSelect(null, c),
                  onKeyDown: (e) => { if (e.key === 'Enter') onSelect(null, c); },
                  onMouseEnter: () => enterHead({ ci, part }),
                  onMouseLeave: hideTip,
                });
                return (
                  <g key={`c${c}`}>
                  <g {...headProps('label')}>
                    <text
                      transform={rotate ? `translate(${cx(ci) - 2},${top - 10}) rotate(-36)` : `translate(${cx(ci)},${top - 12})`}
                      textAnchor={rotate ? 'start' : 'middle'}
                      className={`ax-matrix__collabel ${c === MISSING ? 'is-missing' : ''} ${active?.ci === ci || head?.ci === ci ? 'is-hot' : ''}`}>
                      {label(c)}
                    </text>
                  </g>
                  <g {...headProps('total')}>
                    <rect x={cx(ci) - cw / 2} y={colBarTop - 4} width={cw} height={H - colBarTop + 4} fill="transparent" />
                    <rect x={cx(ci) - 3} y={colBarTop} width={6} height={colBarH} rx={3} className="ax-matrix__track" />
                    <rect x={cx(ci) - 3} width={6} rx={3}
                      y={colBarTop + colBarH - Math.max(2, ((tab.colTotals.get(c) || 0) / maxColN) * colBarH)}
                      height={Math.max(2, ((tab.colTotals.get(c) || 0) / maxColN) * colBarH)}
                      className={`ax-matrix__meter ${c === MISSING ? 'is-missing' : ''}`}
                      style={colColor(c) ? { fill: colColor(c) } : undefined} />
                    <text x={cx(ci)} y={colNumY} textAnchor="middle"
                      className={`ax-matrix__n ${head?.ci === ci ? 'is-hot' : ''}`}>
                      {tab.colTotals.get(c) || 0}
                    </text>
                  </g>
                  </g>
                );
              })}

              {rows.map((r, ri) => {
                const n = tab.rowTotals.get(r) || 0;
                const headProps = (part) => ({
                  className: 'ax-matrix__head',
                  role: 'button',
                  tabIndex: 0,
                  'aria-label': `See all papers with ${rowName}: ${label(r)}`,
                  onClick: () => onSelect(r, null),
                  onKeyDown: (e) => { if (e.key === 'Enter') onSelect(r, null); },
                  onMouseEnter: () => enterHead({ ri, part }),
                  onMouseLeave: hideTip,
                });
                return (
                  <g key={`r${r}`}>
                    <g {...headProps('label')}>
                      <rect x={0} y={top + ri * ch} width={labelW - 6} height={ch} fill="transparent" />
                      <text x={labelW - (rowColor(r) ? 26 : 14)} y={cy(ri)} textAnchor="end" dominantBaseline="central"
                        className={`ax-matrix__rowlabel ${r === MISSING ? 'is-missing' : ''} ${active?.ri === ri || head?.ri === ri ? 'is-hot' : ''}`}>
                        {label(r)}
                      </text>
                      {rowColor(r) && (rowShape(r)
                        ? <path transform={`translate(${labelW - 14}, ${cy(ri)})`} d={shapePath(rowShape(r), 5)} fill={rowColor(r)} />
                        : <circle cx={labelW - 14} cy={cy(ri)} r={4.5} fill={rowColor(r)} />)}
                    </g>
                    <g {...headProps('total')}>
                      <rect x={gridRight + 8} y={top + ri * ch} width={W - gridRight - 8} height={ch} fill="transparent" />
                      <rect x={gridRight + 16} y={cy(ri) - 3} width={48} height={6} rx={3} className="ax-matrix__track" />
                      <rect x={gridRight + 16} y={cy(ri) - 3} width={Math.max(2, (n / maxRowN) * 48)} height={6} rx={3}
                        className={`ax-matrix__meter ${r === MISSING ? 'is-missing' : ''}`}
                        style={rowColor(r) ? { fill: rowColor(r) } : undefined} />
                      <text x={gridRight + 72} y={cy(ri)} dominantBaseline="central"
                        className={`ax-matrix__n ${head?.ri === ri ? 'is-hot' : ''}`}>{n}</text>
                    </g>
                  </g>
                );
              })}

              {rows.map((r, ri) =>
                cols.map((c, ci) => (
                  <rect key={`h${r}|${c}`} x={labelW + ci * cw} y={top + ri * ch} width={cw} height={ch}
                    fill="transparent"
                    onMouseEnter={() => enterCell({ r, c, ri, ci })}
                    onMouseLeave={hideTip}
                    onClick={() => value(r, c) > 0 && onSelect(r, c)}
                    style={{ cursor: value(r, c) > 0 ? 'pointer' : 'default' }} />
                ))
              )}

              {rows.map((r, ri) =>
                cols.map((c, ci) => (value(r, c) === 0
                  ? (
                    <g key={`z${r}|${c}`} pointerEvents="none">
                      {sigOf(r, c) && <circle cx={cx(ci)} cy={cy(ri)} r={7} className="ax-matrix__sigring is-less" />}
                      <circle cx={cx(ci)} cy={cy(ri)} r={1.6} className="ax-matrix__zero" />
                    </g>
                  )
                  : null))
              )}

              {rows.map((r, ri) =>
                cols.map((c, ci) => {
                  const v = value(r, c);
                  if (v === 0) return null;
                  const missing = r === MISSING || c === MISSING;
                  const dim = active && active.ri !== ri && active.ci !== ci;
                  const rad = Math.max(3.5, Math.sqrt(v / max) * rMax);
                  const fill = missing ? null : cellColor(r, c);
                  const txt = fmt(v);
                  const fits = rad >= 11 && rad * 2 >= txt.length * 7 + 8;
                  const isHover = active && active.ri === ri && active.ci === ci;
                  const key = `${r}|${c}`;
                  return (
                    <g key={key} ref={bubbleRef(key)}
                      className={`ax-matrix__cell ${dim ? 'is-dim' : ''} ${isHover ? 'is-hover' : ''}`}
                      onMouseEnter={() => enterCell({ r, c, ri, ci })}
                      onMouseLeave={hideTip}
                      onClick={() => onSelect(r, c)}>
                      <g className="ax-wobble" data-mass={(1.5 - 0.8 * (rad / rMax)).toFixed(2)}>
                        {sigOf(r, c) && (
                          <circle cx={0} cy={0} r={rad + 4} className={`ax-matrix__sigring ${sigOf(r, c).more ? 'is-more' : 'is-less'}`} />
                        )}
                        <circle cx={0} cy={0} style={{ r: rad, ...(fill ? { '--bubble': fill } : {}) }}
                          className={`ax-matrix__bubble ${missing ? 'is-missing' : ''}`} />
                        {fits && (
                          <text x={0} y={0} textAnchor="middle" dominantBaseline="central"
                            className="ax-matrix__value"
                            style={{ fill: missing ? 'var(--text)' : fill ? inkOn(fill) : 'var(--on-accent)' }}>{txt}</text>
                        )}
                      </g>
                    </g>
                  );
                })
              )}

              <text x={gridRight + 16} y={top - 12} className="ax-matrix__marginhead">Total {unitWord}</text>

              <text x={labelW - 14} y={colNumY} textAnchor="end" className="ax-matrix__marginhead">Total {unitWord}</text>

            </svg>

            {tip && (
              <FloatingTip stageRef={stageRef} anchor={tip} contentKey={`${tip.r}|${tip.c}`} onMouseEnter={keepTip} onMouseLeave={hideTip}>
                <div className="ax-tip__title">{tip.title}</div>
                <div className="ax-tip__big">{tip.k} <span>{unitWord}</span></div>
                <div className="ax-tip__row"><span>of all {tip.rn} {label(tip.r)}</span><strong>{pct(tip.rowShare)}</strong></div>
                <div className="ax-tip__row"><span>of all {tip.cn} {label(tip.c)}</span><strong>{pct(tip.colShare)}</strong></div>
                {tip.assoc && <AssocSummary a={tip.assoc} />}
                <div className="ax-tip__actions">
                  {tip.k > 0 && (
                    <button type="button" className="ax-tip__action" onClick={() => onSelect(tip.r, tip.c)}>See these papers →</button>
                  )}
                  {canTrendRow && (
                    <button type="button" className="ax-tip__action" onClick={() => onTrend('row', tip.r)}>
                      <TrendIcon /> {label(tip.r)} over time →
                    </button>
                  )}
                  {canTrendCol && (
                    <button type="button" className="ax-tip__action" onClick={() => onTrend('col', tip.c)}>
                      <TrendIcon /> {label(tip.c)} over time →
                    </button>
                  )}
                </div>
              </FloatingTip>
            )}

            {headTip && (
              <FloatingTip stageRef={stageRef} anchor={headTip} contentKey={`${headTip.kind}|${headTip.value}|${head?.part}`}
                onMouseEnter={keepTip} onMouseLeave={hideTip}>
                <div className="ax-tip__title">{headTip.title}</div>
                <div className="ax-tip__big">{headTip.n} <span>{unitWord}</span></div>
                <div className="ax-tip__actions">
                  <button type="button" className="ax-tip__action"
                    onClick={() => (headTip.kind === 'row' ? onSelect(headTip.value, null) : onSelect(null, headTip.value))}>
                    See these papers →
                  </button>
                  {(headTip.kind === 'row' ? canTrendRow : canTrendCol) && (
                    <button type="button" className="ax-tip__action" onClick={() => onTrend(headTip.kind, headTip.value)}>
                      <TrendIcon /> See trend over time →
                    </button>
                  )}
                </div>
              </FloatingTip>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

function CrossTable({
  tab, rows, cols, mode, value, rowKey, colKey, onSelect, onTrend, canTrendRow, canTrendCol, assocOf, markSig, focus,
}) {
  const sigOf = (r, c) => {
    const a = markSig && assocOf ? assocOf(r, c) : null;
    return a && a.q < ALPHA ? a : null;
  };
  const show = (v) => (mode === 'count' ? v : pct(v));
  const trendBtn = (axis, v) => (
    <button type="button" className="ax-trendbtn" onClick={() => onTrend(axis, v)}
      title={`See trend over time: ${label(v)}`} aria-label={`See trend over time: ${label(v)}`}>
      <TrendIcon />
    </button>
  );
  return (
    <div className="ax-table-wrap">
      <table className="ax-table">
        <thead>
          <tr>
            <th scope="col">{humanize(rowKey)} \ {humanize(colKey)}</th>
            {cols.map((c) => (
              <th key={c} scope="col">
                <span className="ax-headcell">
                  <button type="button" className="ax-cellbtn ax-cellbtn--head" onClick={() => onSelect(null, c)}
                    title={`See all papers: ${label(c)}`}>{label(c)}</button>
                  {canTrendCol && trendBtn('col', c)}
                </span>
              </th>
            ))}
            <th scope="col">Total</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((r) => (
            <tr key={r}>
              <th scope="row">
                <span className="ax-headcell">
                  <button type="button" className="ax-cellbtn ax-cellbtn--head" onClick={() => onSelect(r, null)}
                    title={`See all papers: ${label(r)}`}>{label(r)}</button>
                  {canTrendRow && trendBtn('row', r)}
                </span>
              </th>
              {cols.map((c) => {
                const sig = sigOf(r, c);
                const isFocus = focus && focus.r === r && focus.c === c;
                return (
                  <td key={c} className={`${sig ? (sig.more ? 'is-sig-more' : 'is-sig-less') : ''} ${isFocus ? 'is-focus' : ''}`}
                    title={sig ? `${sig.more ? 'More' : 'Less'} often together than expected (×${sig.ratio.toFixed(2)}, adjusted p ${fmtP(sig.q).replace(/^= /, '')})` : undefined}>
                    {value(r, c) ? (
                      <button type="button" className="ax-cellbtn" onClick={() => onSelect(r, c)}
                        title={`See papers: ${label(r)} × ${label(c)}`}>{show(value(r, c))}</button>
                    ) : <span className="ax-muted">·</span>}
                    {sig && <span className="ax-sigmark" aria-label={sig.more ? 'significantly more often' : 'significantly less often'}>{sig.more ? '↑' : '↓'}</span>}
                  </td>
                );
              })}
              <td className="ax-table__n">
                <button type="button" className="ax-cellbtn ax-cellbtn--muted" onClick={() => onSelect(r, null)}>{tab.rowTotals.get(r)}</button>
              </td>
            </tr>
          ))}
          <tr className="ax-table__foot">
            <th scope="row">Total</th>
            {cols.map((c) => (
              <td key={c} className="ax-table__n">
                <button type="button" className="ax-cellbtn ax-cellbtn--muted" onClick={() => onSelect(null, c)}>{tab.colTotals.get(c)}</button>
              </td>
            ))}
            <td className="ax-table__n"><strong>{tab.n}</strong></td>
          </tr>
        </tbody>
      </table>
    </div>
  );
}

function CooccurrenceView({ papers, colorFor, shapeFor = null, filterNote, aboutOpen }) {
  const [params, update] = useUrlState();
  const navigate = useNavigate();
  const location = useLocation();
  const dimOr = (v, d) => (getDimension(v) ? v : d);
  const unit = 'paper';
  const rowKey = dimOr(params.get('row'), 'type_of_artifact');
  const colKey = dimOr(params.get('col'), 'evaluation_method');
  const mode = ['row', 'col'].includes(params.get('mode')) ? params.get('mode') : 'count';
  const view = params.get('cells') === 'table' ? 'table' : 'bubbles';
  const setRowKey = (v) => update({ row: v });
  const setColKey = (v) => update({ col: v });
  const setMode = (v) => update({ mode: v === 'count' ? null : v });
  const setView = (v) => update({ cells: v === 'bubbles' ? null : v });

  const rowDim = getDimension(rowKey);
  const colDim = getDimension(colKey);
  const units = useMemo(() => buildUnits(papers, unit), [papers, unit]);
  const tab = useMemo(() => crossTab(units, rowDim, colDim), [units, rowDim, colDim]);
  const multiChoice = useMemo(
    () => new Set(DIMENSIONS.filter((d) => choiceProfile(papers, d, unit).multiShare > MULTI_CHOICE_MIN_SHARE).map((d) => d.key)),
    [papers, unit]
  );
  const sameDim = rowKey === colKey;
  const selfCross = sameDim && multiChoice.has(rowKey);

  const rows = tab.rows.filter((r) => r !== MISSING);
  const cols = tab.cols.filter((c) => c !== MISSING);
  const value = (r, c) => {
    if (sameDim && r === c) return 0;
    const k = tab.cell(r, c);
    if (mode === 'row') return tab.rowTotals.get(r) ? k / tab.rowTotals.get(r) : 0;
    if (mode === 'col') return tab.colTotals.get(c) ? k / tab.colTotals.get(c) : 0;
    return k;
  };
  const unitWord = 'papers';

  // Significant relations: Fisher's exact test for every row × column pair.
  const [markSig, setMarkSig] = useState(true);
  const relMethod = CORRECTIONS.some((x) => x.value === params.get('rcorr')) ? params.get('rcorr') : 'bh';
  const setRelMethod = (v) => update({ rcorr: v === 'bh' ? null : v });
  const assoc = useMemo(
    () => (sameDim && !selfCross ? null : associationScan(units, rowDim, colDim, { method: relMethod })),
    [units, rowDim, colDim, sameDim, selfCross, relMethod]
  );
  const assocMap = useMemo(() => new Map((assoc?.rows || []).flatMap((x) => [
    [`${x.r}\u0000${x.c}`, x],
    ...(sameDim ? [[`${x.c}\u0000${x.r}`, { ...x, r: x.c, c: x.r }]] : []),
  ])), [assoc, sameDim]);
  const assocOf = (r, c) => assocMap.get(`${r}\u0000${c}`) || null;
  const [focus, setFocus] = useState(null);
  const matrixRef = useRef(null);
  const [flash, setFlash] = useState(false);
  const flashTimer = useRef(null);
  useEffect(() => () => clearTimeout(flashTimer.current), []);
  const pickRelation = (r, c) => {
    setFocus({ r, c });
    clearTimeout(flashTimer.current);
    setFlash(false);
    requestAnimationFrame(() => {
      setFlash(true);
      flashTimer.current = setTimeout(() => setFlash(false), 1100);
    });
    const el = matrixRef.current;
    if (!el) return;
    const box = el.getBoundingClientRect();
    if (box.top < 0 || box.top > window.innerHeight * 0.4) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
  };

  // A single year has no trend over time, so year gets no trend links.
  const trendable = (dimKey) => dimKey !== 'year';
  const openTrend = (axis, v) => {
    const dimKey = axis === 'row' ? rowKey : colKey;
    update({ view: 'trends', ind: `dim:${dimKey}:${v}` });
    const tabs = document.querySelector('.ax-tabs');
    if (tabs && tabs.getBoundingClientRect().top < 0) tabs.scrollIntoView({ behavior: 'smooth', block: 'start' });
  };

  const openPapers = (r, c) => {
    const ids = [...new Set(units
      .filter((u) => (r === null || unitValues(u, rowDim).includes(r)) && (c === null || unitValues(u, colDim).includes(c)))
      .map((u) => u.paper._id))];
    if (!ids.length) return;
    navigate('/', {
      state: {
        analysisSelection: {
          ids,
          label: r !== null && c !== null
            ? `${label(r)} × ${label(c)}`
            : r !== null ? `${humanize(rowKey)}: ${label(r)}` : `${humanize(colKey)}: ${label(c)}`,
          note: filterNote,
          back: `${location.pathname}${window.location.search}`,
        },
      },
    });
  };

  const exportCsv = () => {
    const header = [`${humanize(rowKey)} \\ ${humanize(colKey)}`, ...cols.map(label), `total_${unitWord}`];
    const body = rows.map((r) => [label(r), ...cols.map((c) => (mode === 'count' ? value(r, c) : value(r, c).toFixed(4))), tab.rowTotals.get(r)]);
    const footer = [`total_${unitWord}`, ...cols.map((c) => tab.colTotals.get(c)), tab.n];
    downloadCsv(`crosstab_${rowKey}_x_${colKey}_${unit}_${mode}.csv`, [header, ...body, footer]);
  };

  const dimOptions = (otherKey) => DIMENSIONS.map((d) => (
    <option key={d.key} value={d.key} disabled={d.key === otherKey && !multiChoice.has(d.key)}>{humanize(d.key)}</option>
  ));

  return (
    <>
    <div className={`ax-frame ${flash ? 'ax-frame--flash' : ''}`} ref={matrixRef}>
      <div className="ax-toolbar ax-toolbar--stack">
        <div className="ax-toolbar__row">
          <div className="ax-field ax-field--pair">
            <Select id="ct-row" value={rowKey} onChange={setRowKey} labelText="Rows">{dimOptions(colKey)}</Select>
            <button type="button" className="graph-controls__btn ax-iconbtn" onClick={() => update({ row: colKey, col: rowKey })}
              title="Swap rows and columns" aria-label="Swap rows and columns">
              <svg viewBox="0 0 16 16" width="14" height="14" aria-hidden="true">
                <path d="M3 5h10m0 0-2.5-2.5M13 5l-2.5 2.5M13 11H3m0 0 2.5-2.5M3 11l2.5 2.5" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
              </svg>
            </button>
            <Select id="ct-col" value={colKey} onChange={setColKey} labelText="Columns">{dimOptions(rowKey)}</Select>
          </div>
          <div className="graph-controls__spacer" />
          <Chips ariaLabel="View" value={view} onChange={setView}
            options={[{ value: 'bubbles', label: 'Bubbles' }, { value: 'table', label: 'Table' }]} />
          <ExportButton onClick={exportCsv} />
        </div>
        <div className="ax-toolbar__row">
          <Chips labelText="Show" ariaLabel="Cell values" value={mode} onChange={setMode}
            options={[
              { value: 'count', label: 'Absolute numbers' },
              { value: 'row', label: 'Relative % per row' },
              { value: 'col', label: 'Relative % per column' },
            ]} />
          <div className="graph-controls__spacer" />
          {assoc && <Toggle checked={markSig} onChange={setMarkSig}>Mark significant</Toggle>}
          <ShapesToggle />
        </div>
      </div>

      {assoc && markSig && (
        <div className="ax-siglegend">
          <span><svg width="18" height="18" aria-hidden="true"><circle cx="9" cy="9" r="6" className="ax-matrix__sigring is-more" /></svg>More often together than expected</span>
          <span><svg width="18" height="18" aria-hidden="true"><circle cx="9" cy="9" r="6" className="ax-matrix__sigring is-less" /></svg>Less often together than expected</span>
          <span className="ax-siglegend__note">Fisher&apos;s exact test, adjusted p &lt; {ALPHA} ({CORRECTIONS.find((x) => x.value === relMethod).label})</span>
        </div>
      )}

      <AboutPanel open={aboutOpen} id="ct-about">
        <dl className="ax-howto">
          <dt>Bubbles</dt>
          <dd>
            Size = number of {unitWord} that have both codes. One {unitWord.slice(0, -1)} can have several codes per
            dimension, so cells do not add up to the totals. The bars on the right and at the bottom show each
            row&apos;s and column&apos;s total. &quot;Relative % per row/column&quot; shows each cell as a share of its
            row or column total.
          </dd>
          <dt>Significant relations</dt>
          <dd>
            A ring marks a pair that occurs significantly <strong>more often</strong> (solid ring) or{' '}
            <strong>less often</strong> (dashed ring) together than expected if the two codes were unrelated. The
            tooltip shows the <em>expected</em> count and the <em>ratio</em> observed ÷ expected: ×2 means twice as
            often as expected, ×0.5 half as often.
          </dd>
          <dt>The test</dt>
          <dd>
            Each pair gets Fisher&apos;s exact test on a 2×2 table (has the row code or not × has the column code or
            not), counting only the {unitWord} coded on both dimensions. H₀: the two codes occur together as often
            as chance predicts. Because every pair is tested, p-values are adjusted for multiple testing
            (Benjamini–Hochberg by default; Holm is stricter). A pair counts as significant if its adjusted p &lt;{' '}
            {ALPHA}. &quot;Significant Relations&quot; below lists all pairs this way; click one to find it here.
          </dd>
          <dt>Read with care</dt>
          <dd>
            A significant relation shows that two codes go together more (or less) than chance would suggest, not
            that one causes the other. With small counts even large ratios are rarely significant, and the result
            depends on the filters.
          </dd>
          <dt>Interacting</dt>
          <dd>
            Click a bubble, a row or a column name to see its papers. Hover one for its numbers and a link to its
            trend over time.
          </dd>
        </dl>
      </AboutPanel>

      {sameDim && !selfCross ? (
        <div className="ax-empty">
          {humanize(rowKey)} has one value per {unitWord.slice(0, -1)}, so it cannot be crossed with itself. Pick two
          different dimensions.
        </div>
      ) : view === 'bubbles' ? (
        <BubbleMatrix tab={tab} rows={rows} cols={cols} mode={mode} value={value} unitWord={unitWord}
          rowName={humanize(rowKey)} colName={humanize(colKey)}
          rowColor={(r) => colorFor(rowKey, r)} colColor={(c) => colorFor(colKey, c)}
          rowShape={(r) => shapeFor?.(rowKey, r) || null} onSelect={openPapers}
          onTrend={openTrend} canTrendRow={trendable(rowKey)} canTrendCol={trendable(colKey)}
          assocOf={assocOf} markSig={markSig} focus={focus} onClearFocus={() => setFocus(null)} />
      ) : (
        <CrossTable tab={tab} rows={rows} cols={cols} mode={mode} value={value} rowKey={rowKey} colKey={colKey}
          onSelect={openPapers} onTrend={openTrend} canTrendRow={trendable(rowKey)} canTrendCol={trendable(colKey)}
          assocOf={assocOf} markSig={markSig} focus={focus} />
      )}
    </div>

    {assoc && (
      <SignificantRelations assoc={assoc} rowName={humanize(rowKey)} colName={humanize(colKey)} unitWord={unitWord}
        method={relMethod} setMethod={setRelMethod} focus={focus} onPick={pickRelation}
        rowColor={(r) => colorFor(rowKey, r)} colColor={(c) => colorFor(colKey, c)}
        rowShape={(r) => shapeFor?.(rowKey, r) || null} colShape={(c) => shapeFor?.(colKey, c) || null} />
    )}
    </>
  );
}

const fmtRatio = (x) => (Number.isFinite(x) ? `×${x < 10 ? x.toFixed(2) : x.toFixed(1)}` : '—');

/** Expected count, ratio, p-values and verdict for one row × column pair. */
function AssocSummary({ a }) {
  const sig = a.q < ALPHA;
  return (
    <div className={`ax-tip__stat ${sig ? 'is-sig' : ''}`}>
      <div className="ax-tip__row"><span>expected if unrelated</span><strong>{a.expected.toFixed(1)}</strong></div>
      <div className="ax-tip__row"><span>observed ÷ expected</span><strong>{fmtRatio(a.ratio)}</strong></div>
      <div className="ax-tip__row"><span>p · adjusted p</span><strong>{fmtP(a.p).replace(/^= /, '')} · {fmtP(a.q).replace(/^= /, '')}</strong></div>
      <span className="ax-verdict">
        <span className="ax-verdict__icon" aria-hidden="true">{sig ? (a.more ? '↑' : '↓') : '–'}</span>
        {sig ? `Significantly ${a.more ? 'more' : 'less'} often together` : 'Not significant'}
      </span>
    </div>
  );
}

/**
 * Lists the row × column pairs of the co-occurrence matrix by adjusted
 * p-value (Fisher's exact test per pair), like Significant Trends. Clicking a
 * row highlights that cell in the matrix above.
 */
function ChipDot({ color, shape }) {
  if (!color) return null;
  if (shape) {
    return (
      <span className="fs-chip__dot fs-chip__dot--shape" aria-hidden="true">
        <ShapeIcon shape={shape} color={color} size={10} />
      </span>
    );
  }
  return <span className="fs-chip__dot" style={{ background: color }} />;
}

function SignificantRelations({ assoc, rowName, colName, unitWord, method, setMethod, focus, onPick, rowColor, colColor, rowShape, colShape }) {
  const [showAll, setShowAll] = useState(false);
  const { rows, n } = assoc;
  const significant = rows.filter((x) => x.q < ALPHA);
  const visible = showAll ? rows : significant.length ? significant : rows.slice(0, SCAN_FALLBACK_ROWS);
  const methodInfo = CORRECTIONS.find((x) => x.value === method);

  const exportCsv = () => {
    downloadCsv(`significant_relations_${method}.csv`, [
      [rowName, colName, 'together', 'expected', 'ratio', 'odds_ratio', 'row_total', 'column_total', 'n', 'p_fisher', 'p_adjusted', 'adjustment', 'significant', 'direction'],
      ...rows.map((x) => [label(x.r), label(x.c), x.observed, x.expected.toFixed(2), Number.isFinite(x.ratio) ? x.ratio.toFixed(3) : '',
        x.oddsRatio.toFixed(3), x.rowN, x.colN, x.n, x.p.toExponential(4), x.q.toExponential(4), method, x.q < ALPHA ? 'yes' : 'no',
        x.more ? 'more' : 'less']),
    ]);
  };

  if (!rows.length) return null;

  return (
    <section className="ax-frame ax-scan" aria-labelledby="ax-rel-title">
      <div className="ax-toolbar ax-scan__toolbar">
        <div className="ax-scan__title">
          <h2 id="ax-rel-title">Significant Relations</h2>
          <p>
            {significant.length
              ? `${significant.length} of ${rows.length} ${rowName} × ${colName} pairs occur significantly more or less often together than expected`
              : `None of the ${rows.length} ${rowName} × ${colName} pairs differs significantly from what is expected`}{' '}
            (Fisher&apos;s exact test on {n} {unitWord} coded on both, {methodInfo.short}, adjusted p &lt; {ALPHA}).
            Click a row to find it in the matrix.
          </p>
        </div>
        <div className="graph-controls__spacer" />
        <Chips labelText="Adjust p" ariaLabel="Multiple-testing adjustment" value={method} onChange={setMethod}
          options={CORRECTIONS.map((x) => ({ value: x.value, label: x.label }))} />
        <Toggle checked={showAll} onChange={setShowAll}>Show all {rows.length}</Toggle>
        <ExportButton onClick={exportCsv} />
      </div>

      {!showAll && !significant.length && (
        <p className="ax-scan__note">Showing the {Math.min(SCAN_FALLBACK_ROWS, rows.length)} pairs with the lowest p-values.</p>
      )}

      <div className="ax-table-wrap">
        <table className="ax-table ax-scan__table">
          <thead>
            <tr>
              <th scope="col">{rowName} × {colName}</th>
              <th scope="col" className="ax-num">Together</th>
              <th scope="col" className="ax-num" title="Count expected if the two codes were unrelated">Expected</th>
              <th scope="col" className="ax-num" title="Observed ÷ expected: ×2 = twice as often as expected">Ratio</th>
              <th scope="col" className="ax-num">p</th>
              <th scope="col" className="ax-num">Adjusted p</th>
              <th scope="col">Result</th>
            </tr>
          </thead>
          <tbody>
            {visible.map((x) => {
              const sig = x.q < ALPHA;
              const isFocus = focus && focus.r === x.r && focus.c === x.c;
              return (
                <tr key={`${x.r}|${x.c}`} onClick={() => onPick(x.r, x.c)}
                  className={`ax-scan__row ${sig ? 'is-sig' : ''} ${sig && !x.more ? 'is-less' : ''} ${isFocus ? 'is-active' : ''}`}>
                  <th scope="row">
                    <button type="button" className="ax-scan__pick ax-rel__pick" aria-pressed={isFocus}
                      onClick={(e) => { e.stopPropagation(); onPick(x.r, x.c); }} title="Find this pair in the matrix">
                      <span className="ax-rel__pair">
                        <span className="ax-rel__val"><ChipDot color={rowColor(x.r)} shape={rowShape(x.r)} />{label(x.r)}</span>
                        <span className="ax-rel__x" aria-hidden="true">×</span>
                        <span className="ax-rel__val"><ChipDot color={colColor(x.c)} shape={colShape(x.c)} />{label(x.c)}</span>
                      </span>
                    </button>
                  </th>
                  <td className="ax-num">{x.observed}</td>
                  <td className="ax-num">{x.expected.toFixed(1)}</td>
                  <td className="ax-num">{fmtRatio(x.ratio)}</td>
                  <td className="ax-num">{fmtP(x.p).replace(/^= /, '')}</td>
                  <td className="ax-num ax-scan__q">{fmtP(x.q).replace(/^= /, '')}</td>
                  <td>
                    <span className="ax-verdict">
                      <span className="ax-verdict__icon" aria-hidden="true">{sig ? (x.more ? '↑' : '↓') : '–'}</span>
                      {sig ? (x.more ? 'More often together' : 'Less often together') : 'Not significant'}
                    </span>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </section>
  );
}

function TrackKey({ dash }) {
  return (
    <svg className="ax-trackkey" width="22" height="8" aria-hidden="true">
      <line x1="1" x2="21" y1="4" y2="4" strokeDasharray={dash || 'none'} />
    </svg>
  );
}

function useHeight() {
  const [height, setHeight] = useState(0);
  const observer = useRef(null);
  const ref = useCallback((el) => {
    observer.current?.disconnect();
    observer.current = null;
    if (!el) {
      setHeight(0);
      return;
    }
    setHeight(el.getBoundingClientRect().height);
    observer.current = new ResizeObserver(([entry]) => setHeight(entry.contentRect.height));
    observer.current.observe(el);
  }, []);
  return [ref, height];
}

function TrendChart({ series, years, animKey, height = 280 }) {
  const [ref, width] = useWidth();
  const [hoverYear, setHoverYear] = useState(null);
  const single = series.length === 1;
  const H = Math.max(280, Math.round(height));
  const m = { t: 16, r: 20, b: 30, l: 40 };
  const W = Math.max(260, width);
  const iw = W - m.l - m.r;
  const ih = H - m.t - m.b;
  const minY = Math.min(...years);
  const maxY = Math.max(...years);
  const step = years.length > 1 ? iw / (years.length - 1) : iw;
  const labelEvery = Math.ceil(years.length / 12);
  const x = (yr) => m.l + (maxY === minY ? iw / 2 : ((yr - minY) / (maxY - minY)) * iw);
  const y = (p) => m.t + (1 - p) * ih;

  const hoverRows = hoverYear === null ? [] : series
    .map((s) => ({ s, p: s.points.find((pt) => pt.x === hoverYear) }))
    .filter((d) => d.p);

  return (
    <div className="ax-trend" ref={ref}>
      {width > 0 && years.length > 0 && (
        <>
          <svg key={animKey} width={W} height={H} className="ax-trend__svg" role="img"
            aria-label="Share of papers per year; the table lists every value" style={{ '--series': series[0]?.color }}>
            <defs>
              <linearGradient id="ax-area" x1="0" x2="0" y1="0" y2="1">
                <stop offset="0%" stopColor="var(--series)" stopOpacity="0.22" />
                <stop offset="100%" stopColor="var(--series)" stopOpacity="0.02" />
              </linearGradient>
            </defs>
            {[0, 0.25, 0.5, 0.75, 1].map((t) => (
              <g key={t}>
                <line x1={m.l} x2={W - m.r} y1={y(t)} y2={y(t)} className="ax-trend__grid" />
                <text x={m.l - 10} y={y(t)} textAnchor="end" dominantBaseline="central" className="ax-trend__tick">{t * 100}%</text>
              </g>
            ))}
            {years.filter((yr) => (yr - minY) % labelEvery === 0 || yr === hoverYear).map((yr) => (
              <text key={yr} x={x(yr)} y={H - 8} textAnchor="middle"
                className={`ax-trend__tick ${hoverYear === yr ? 'is-hot' : ''}`}>{yr}</text>
            ))}

            {hoverYear !== null && <line x1={x(hoverYear)} x2={x(hoverYear)} y1={m.t} y2={m.t + ih} className="ax-trend__cross" />}

            {series.map((s) => {
              const pts = s.points.filter((p) => p.n > 0);
              if (!pts.length) return null;
              const runs = pts.reduce((acc, p, i) => {
                if (i && p.x - pts[i - 1].x > 1) acc.push([]);
                acc[acc.length - 1].push(p);
                return acc;
              }, [[]]);
              const path = (r, f) => r.map((p, i) => `${i ? 'L' : 'M'}${x(p.x)},${y(f(p))}`).join('');
              const line = runs.map((r) => path(r, (p) => p.p)).join('');
              const band = runs.map((r) => `${path(r, (p) => p.hi)}${[...r].reverse().map((p) => `L${x(p.x)},${y(p.lo)}`).join('')}Z`).join('');
              const area = runs.map((r) => `${path(r, (p) => p.p)}L${x(r[r.length - 1].x)},${y(0)}L${x(r[0].x)},${y(0)}Z`).join('');
              return (
                <g key={s.name} style={{ '--series': s.color }}>
                  {single && <path d={area} fill="url(#ax-area)" className="ax-trend__fade" />}
                  {single && <path d={band} className="ax-trend__band ax-trend__fade" />}
                  {s.dash && s.dash !== 'none' ? (
                    <path d={line} className="ax-trend__line ax-trend__fade" strokeDasharray={s.dash} />
                  ) : (
                    <path d={line} className="ax-trend__line ax-trend__draw" pathLength="1" />
                  )}
                  {pts.map((p, i) => (
                    <circle key={p.x} cx={x(p.x)} cy={y(p.p)} r={hoverYear === p.x ? 6 : single ? 4.5 : 3.5}
                      className={`ax-trend__dot ${p.n < MIN_YEAR_N ? 'ax-trend__dot--few' : ''}`} style={{ '--d': `${300 + i * 70}ms` }} />
                  ))}
                </g>
              );
            })}

            {years.map((yr) => (
              <rect key={`h${yr}`} x={x(yr) - step / 2} y={m.t} width={step} height={ih} fill="transparent"
                onMouseEnter={() => setHoverYear(yr)} onMouseLeave={() => setHoverYear(null)} />
            ))}
          </svg>

          {hoverRows.length > 0 && (
            <div className={`ax-tip ax-tip--trend ${x(hoverYear) > W * 0.7 ? 'ax-tip--left' : ''}`}
              style={{ left: x(hoverYear), top: m.t }}>
              <div className="ax-tip__title">{hoverYear}</div>
              {hoverRows.map(({ s, p }) => (
                <div key={s.name} className="ax-tip__series">
                  {!single && <TrackKey dash={s.dash} />}
                  <span>{single ? `${p.k} of ${p.n} papers` : s.name}</span>
                  <strong>{pct(p.p)}</strong>
                  <span className="ax-tip__ci">{single ? `95% CI ${pct(p.lo)}–${pct(p.hi)}` : `${p.k} of ${p.n} papers`}</span>
                </div>
              ))}
            </div>
          )}
        </>
      )}
    </div>
  );
}

function TrendsView({ papers, colorFor, aboutOpen }) {
  const [params, update] = useUrlState();
  const [factsRef, factsHeight] = useHeight();
  const [legendRef, legendHeight] = useHeight();
  const indicatorId = params.get('ind') || INDICATORS[0].id;
  const split = params.get('split') === '1';
  const showTable = params.get('ttable') === '1';
  const setIndicatorId = (v) => update({ ind: v === INDICATORS[0].id ? null : v });
  const setSplit = (v) => update({ split: v });
  const setShowTable = (v) => update({ ttable: v });
  const indicator = useMemo(() => resolveIndicator(indicatorId), [indicatorId]);
  const indicatorColor = useMemo(() => {
    const [kind, key, ...rest] = indicatorId.split(':');
    return kind === 'dim' ? colorFor(key, rest.join(':')) : null;
  }, [indicatorId, colorFor]);

  const valueGroups = useMemo(() => {
    const units = buildUnits(papers, 'paper');
    return DIMENSIONS.filter((d) => d.key !== 'year').map((d) => {
      const vals = new Set();
      units.forEach((u) => unitValues(u, d).forEach((v) => v !== MISSING && vals.add(v)));
      return { dim: d, values: [...vals].sort() };
    });
  }, [papers]);

  const overall = useMemo(() => yearlyTrend(papers, indicator), [papers, indicator]);
  const years = overall.length
    ? Array.from({ length: overall[overall.length - 1].x - overall[0].x + 1 }, (_, i) => overall[0].x + i)
    : [];
  const test = useMemo(() => cochranArmitage(overall), [overall]);
  const tracks = useMemo(() => [...new Set(papers.map((p) => p.metadata?.track).filter(Boolean))].sort(), [papers]);
  const canSplit = tracks.length > 1;
  const isSplit = split && canSplit;

  const shownTracks = useMemo(() => tracks.slice(0, TRACK_DASHES.length), [tracks]);

  const series = isSplit
    ? shownTracks.map((t, i) => ({
        name: t,
        color: indicatorColor || 'var(--accent)',
        dash: TRACK_DASHES[i],
        points: yearlyTrend(papers.filter((p) => p.metadata?.track === t), indicator),
      }))
    : [{ name: 'All papers', color: indicatorColor || 'var(--accent)', points: overall }];

  // Share, change and trend test for each track on its own (split view).
  const trackStats = isSplit
    ? series.map((sr) => {
        const tot = sr.points.reduce((acc, g) => ({ n: acc.n + g.n, k: acc.k + g.k }), { n: 0, k: 0 });
        return { ...sr, total: tot, fit: fittedChange(sr.points), test: cochranArmitage(sr.points) };
      })
    : [];

  const total = overall.reduce((s, g) => ({ n: s.n + g.n, k: s.k + g.k }), { n: 0, k: 0 });
  const fit = useMemo(() => fittedChange(overall), [overall]);
  const exportCsv = () => {
    const rows = [['series', 'year', 'n_papers', 'k_meeting_indicator', 'share', 'wilson95_lo', 'wilson95_hi']];
    series.forEach((s) =>
      s.points.forEach((p) => rows.push([s.name, p.x, p.n, p.k, p.p.toFixed(4), p.lo.toFixed(4), p.hi.toFixed(4)]))
    );
    downloadCsv(`trend_${indicatorId.replace(/[^a-z0-9]+/gi, '_')}.csv`, rows);
  };

  const frameRef = useRef(null);
  const [flash, setFlash] = useState(false);
  const flashTimer = useRef(null);
  useEffect(() => () => clearTimeout(flashTimer.current), []);
  const pickIndicator = (id) => {
    setIndicatorId(id);
    // Briefly outline the chart so the change is noticeable.
    clearTimeout(flashTimer.current);
    setFlash(false);
    requestAnimationFrame(() => {
      setFlash(true);
      flashTimer.current = setTimeout(() => setFlash(false), 1100);
    });
    const el = frameRef.current;
    if (!el) return;
    const r = el.getBoundingClientRect();
    if (r.top < 0 || r.top > window.innerHeight * 0.4) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
  };

  return (
    <>
    <div className={`ax-frame ${flash ? 'ax-frame--flash' : ''}`} ref={frameRef}>
      <div className="ax-toolbar">
        <Select id="tr-ind" value={indicatorId} onChange={setIndicatorId} labelText="Share of papers that">
          <optgroup label="Empirical & Experimental Evidence">
            {INDICATORS.map((i) => <option key={i.id} value={i.id}>{i.label}</option>)}
          </optgroup>
          {valueGroups.map(({ dim, values }) => (
            <optgroup key={dim.key} label={`Has ${humanize(dim.key)}`}>
              {values.map((v) => <option key={v} value={`dim:${dim.key}:${v}`}>{humanize(v)}</option>)}
            </optgroup>
          ))}
        </Select>
        <div className="graph-controls__spacer" />
        {canSplit && <Toggle checked={split} onChange={setSplit}>Split by track</Toggle>}
        <Toggle checked={showTable} onChange={setShowTable}>Table</Toggle>
        <ExportButton onClick={exportCsv} />
      </div>

      <AboutPanel open={aboutOpen} id="tr-about">
        <dl className="ax-howto">
          <dt>The line</dt>
          <dd>
            Share of papers per year that meet the indicator
            {indicatorId === 'empirical_eval' && ` (empirical = ${EMPIRICAL_EVAL_METHODS.map(humanize).join(', ')})`}.
            The band is the 95% Wilson confidence interval. With about{' '}
            {Math.round(total.n / Math.max(1, years.length))} papers per year, single years should be read with care;
            years with fewer than {MIN_YEAR_N} papers are drawn hollow.
          </dd>
          <dt>Change (pp)</dt>
          <dd>
            Change over the whole period in <strong>percentage points</strong> (pp), the difference between two
            percentages: 20% → 50% is +30 pp. It is read off a straight line fitted to all years, so single noisy
            years do not dominate it.
          </dd>
          <dt>Trend test</dt>
          <dd>
            Cochran–Armitage test{isSplit ? ', run for each track separately' : ''}. H₀: the share does not change
            linearly over the years. If p &lt; {ALPHA}, H₀ is rejected and the trend is statistically significant
            (↑ upward, ↓ downward); otherwise the data give no evidence of a trend. Not rejecting H₀ does not prove
            the share is stable.
          </dd>
          <dt>Significant Trends</dt>
          <dd>
            Tests every indicator and every coded value found in at least {SCAN_MIN_PAPERS} papers at once.
            Duplicate and mirrored tests are counted once. Because many trends are tested, p-values are adjusted
            (Benjamini–Hochberg by default; Holm is stricter); a trend counts as significant if its adjusted p &lt;{' '}
            {ALPHA}. With &quot;Split by track&quot;, each track is tested on its own and all tests are adjusted
            together. Click a row to show that trend in the chart.
          </dd>
          <dt>Read with care</dt>
          <dd>
            A significant trend shows that a share changed steadily over time in this collection, not why. Results
            depend on the filters, and a straight-line test can miss changes that go up and then down.
          </dd>
        </dl>
      </AboutPanel>

      {total.n === 0 ? (
        <div className="ax-empty">No papers match the current filters.</div>
      ) : (
        <div className="ax-trend-layout">
          <div className="ax-trend-main">
            {isSplit && (
              <ul className="ax-legend" ref={legendRef}>
                {series.map((s) => <li key={s.name}><TrackKey dash={s.dash} />{s.name}</li>)}
              </ul>
            )}
            <TrendChart series={series} years={years} animKey={`${indicatorId}|${isSplit}`}
              height={factsHeight - (isSplit ? legendHeight + LEGEND_GAP : 0)} />
          </div>

          <aside className={`ax-facts ${isSplit ? 'ax-facts--tracks' : ''}`} ref={factsRef}>
            {isSplit ? (
              trackStats.map((t) => (
                <TestTile key={t.name} test={t.test} id={`tr-test-${t.name}`}
                  header={<span className="ax-fact__track"><TrackKey dash={t.dash} />{t.name}</span>}
                  detail={<>{t.total.n ? pct(t.total.k / t.total.n) : '—'} of {t.total.n} papers
                    {t.fit.change !== null && <> · <PP value={t.fit.change} /> fitted ({t.fit.from}–{t.fit.to})</>}</>} />
              ))
            ) : (
              <>
                <div className="stats-bar__tile ax-fact">
                  <span className="stats-bar__value">{pct(total.k / total.n)}</span>
                  <span className="stats-bar__label">Overall · {total.k} of {total.n} papers</span>
                </div>
                {fit.change !== null && (
                  <div className="stats-bar__tile ax-fact">
                    <span className="stats-bar__value"><PP value={fit.change} /></span>
                    <span className="stats-bar__label">Fitted change {fit.from} → {fit.to} · percentage points</span>
                  </div>
                )}
                <TestTile test={test} id="tr-test-info" />
              </>
            )}
          </aside>
        </div>
      )}

      {showTable && total.n > 0 && (
        <div className="ax-table-wrap">
          <table className="ax-table ax-table--num">
            <thead>
              <tr>{isSplit && <th scope="col">Track</th>}<th scope="col">Year</th><th scope="col">Papers</th><th scope="col">Meeting indicator</th><th scope="col">Share</th><th scope="col">95% CI</th></tr>
            </thead>
            <tbody>
              {series.flatMap((sr) => sr.points.map((g) => (
                <tr key={`${sr.name}|${g.x}`}>
                  {isSplit && <td>{sr.name}</td>}
                  <th scope="row">{g.x}</th><td>{g.n}</td><td>{g.k}</td><td>{pct(g.p, 1)}</td><td>{pct(g.lo, 1)} – {pct(g.hi, 1)}</td>
                </tr>
              )))}
            </tbody>
          </table>
        </div>
      )}
    </div>

    <SignificantTrends papers={papers} tracks={shownTracks} split={isSplit} colorFor={colorFor}
      activeId={indicatorId} onPick={pickIndicator} />
    </>
  );
}

/** p-value tile: value with a (?) explanation, H₀ verdict and direction. */
function TestTile({ test, id, header, detail }) {
  const significant = test && test.p < ALPHA;
  return (
    <div className={`stats-bar__tile ax-fact ax-fact--test ${test ? (significant ? 'is-rejected' : 'is-kept') : ''}`}>
      {header}
      <span className="ax-fact__pline">
        <span className="stats-bar__value">{test ? `p ${fmtP(test.p)}` : '—'}</span>
        {test && (
          <InfoTip id={id}>
            <strong>{significant ? `H₀ rejected (p < ${ALPHA})` : `H₀ not rejected (p ≥ ${ALPHA})`}</strong>
            <br />
            H₀: the share of papers does not change linearly over the years. Cochran–Armitage trend test,
            significance level α = {ALPHA}. This tests one trend on its own; when comparing many, use the
            adjusted p in Significant Trends below.
          </InfoTip>
        )}
      </span>
      {test ? (
        <>
          <span className="ax-verdict">
            <span className="ax-verdict__icon" aria-hidden="true">{significant ? (test.z > 0 ? '↑' : '↓') : '–'}</span>
            {significant ? 'H₀ rejected' : 'H₀ not rejected'}
          </span>
          <span className="ax-fact__sub">
            {significant ? `Significant ${test.z > 0 ? 'upward' : 'downward'} trend` : 'No evidence of a trend'}
          </span>
        </>
      ) : (
        <span className="stats-bar__label">Trend test n/a</span>
      )}
      {detail && <span className="ax-fact__sub ax-fact__detail">{detail}</span>}
    </div>
  );
}

function InfoTip({ id, children }) {
  return (
    <span className="ax-info">
      <button type="button" className="ax-info__btn" aria-describedby={id} aria-label="What does this mean?">?</button>
      <span role="tooltip" id={id} className="ax-info__tip">{children}</span>
    </span>
  );
}

const CORRECTIONS = [
  { value: 'bh', label: 'Benjamini–Hochberg', short: 'Benjamini–Hochberg (false discovery rate)' },
  { value: 'holm', label: 'Holm', short: 'Holm–Bonferroni (family-wise error rate)' },
  { value: 'none', label: 'None', short: 'no adjustment' },
];
const SCAN_MIN_PAPERS = 5;
const SCAN_FALLBACK_ROWS = 5;

function Sparkline({ points, yearMin, yearMax, color }) {
  const w = 84;
  const h = 22;
  const pts = points.filter((p) => p.n > 0);
  if (pts.length < 2) return null;
  const x = (yr) => (yearMax === yearMin ? w / 2 : ((yr - yearMin) / (yearMax - yearMin)) * (w - 4) + 2);
  const y = (p) => 2 + (1 - p) * (h - 4);
  const d = pts.map((p, i) => `${i ? 'L' : 'M'}${x(p.x).toFixed(1)},${y(p.p).toFixed(1)}`).join('');
  return (
    <svg className="ax-spark" width={w} height={h} viewBox={`0 0 ${w} ${h}`} aria-hidden="true">
      <line x1="0" x2={w} y1={h - 2} y2={h - 2} className="ax-spark__base" />
      <path d={d} className="ax-spark__line" style={color ? { stroke: color } : undefined} />
      <circle cx={x(pts[pts.length - 1].x)} cy={y(pts[pts.length - 1].p)} r="2" className="ax-spark__dot"
        style={color ? { fill: color } : undefined} />
    </svg>
  );
}

const scanLabel = (r) => r.label || humanize(r.value);
const scanGroup = (r) => (r.dimKey ? humanize(r.dimKey) : r.group);

/** "+12 pp" with the unit spelled out for screen readers and on hover. */
function PP({ value }) {
  if (value === null || value === undefined || !Number.isFinite(value)) return <>—</>;
  return (
    <>
      {value >= 0 ? '+' : '−'}{Math.abs(Math.round(value * 100))}{' '}
      <abbr title="percentage points" className="ax-pp">pp</abbr>
    </>
  );
}

/**
 * Tests the trend of every indicator and coded value at once and lists them by
 * adjusted p-value, so trends that hold up after correcting for multiple
 * testing stand out. With "Split by track" on, every track is tested on its
 * own and all tests are adjusted together. Clicking a row shows that trend in
 * the chart above.
 */
function SignificantTrends({ papers, tracks, split, activeId, onPick, colorFor }) {
  const [params, update] = useUrlState();
  const method = CORRECTIONS.some((c) => c.value === params.get('corr')) ? params.get('corr') : 'bh';
  const setMethod = (v) => update({ corr: v === 'bh' ? null : v });
  const [showAll, setShowAll] = useState(false);

  const rows = useMemo(
    () => (split
      ? trendScanByTrack(papers, tracks, { method, minPapers: SCAN_MIN_PAPERS })
      : trendScan(papers, { method, minPapers: SCAN_MIN_PAPERS })),
    [papers, tracks, split, method]
  );
  const years = papers.map((p) => p.metadata?.year).filter(Boolean);
  const yearMin = Math.min(...years);
  const yearMax = Math.max(...years);
  const significant = rows.filter((r) => r.q < ALPHA);
  const visible = showAll ? rows : significant.length ? significant : rows.slice(0, SCAN_FALLBACK_ROWS);
  const methodInfo = CORRECTIONS.find((c) => c.value === method);
  const dashOf = (track) => TRACK_DASHES[tracks.indexOf(track)] || 'none';
  const testedWhat = split ? `${rows.length} trends (${tracks.length} tracks tested separately)` : `${rows.length} trends`;

  const exportCsv = () => {
    downloadCsv(`significant_trends_${split ? 'by_track_' : ''}${method}.csv`, [
      [...(split ? ['track'] : []), 'indicator', 'group', 'overall_share', 'fitted_change_percentage_points', 'from_year', 'to_year', 'z', 'p', 'p_adjusted', 'adjustment', 'significant'],
      ...rows.map((r) => [...(split ? [r.track] : []), scanLabel(r), scanGroup(r), r.share.toFixed(4), r.change === null ? '' : (r.change * 100).toFixed(1),
        r.changeFrom ?? '', r.changeTo ?? '', r.z.toFixed(3), r.p.toFixed(5), r.q.toFixed(5), method, r.q < ALPHA ? 'yes' : 'no']),
    ]);
  };

  if (!rows.length) return null;

  return (
    <section className="ax-frame ax-scan" aria-labelledby="ax-scan-title">
      <div className="ax-toolbar ax-scan__toolbar">
        <div className="ax-scan__title">
          <h2 id="ax-scan-title">Significant Trends{split ? ' by Track' : ''}</h2>
          <p>
            {significant.length
              ? `${significant.length} of ${testedWhat} are significant`
              : `None of the ${testedWhat} is significant`}{' '}
            after adjusting for testing them all at once ({methodInfo.short}, adjusted p &lt; {ALPHA}).
            Click a row to show it in the chart.
          </p>
        </div>
        <div className="graph-controls__spacer" />
        <Chips labelText="Adjust p" ariaLabel="Multiple-testing adjustment" value={method} onChange={setMethod}
          options={CORRECTIONS.map((c) => ({ value: c.value, label: c.label }))} />
        <Toggle checked={showAll} onChange={setShowAll}>Show all {rows.length}</Toggle>
        <ExportButton onClick={exportCsv} />
      </div>

      {!showAll && !significant.length && (
        <p className="ax-scan__note">Showing the {Math.min(SCAN_FALLBACK_ROWS, rows.length)} trends with the lowest p-values.</p>
      )}

      <div className="ax-table-wrap">
        <table className="ax-table ax-scan__table">
          <thead>
            <tr>
              <th scope="col">Share of papers that…</th>
              {split && <th scope="col">Track</th>}
              <th scope="col">{yearMin}–{yearMax}</th>
              <th scope="col" title="Change over the whole period along a straight line fitted to the yearly shares, in percentage points">
                Fitted change
              </th>
              <th scope="col">p</th>
              <th scope="col">Adjusted p</th>
              <th scope="col">Result</th>
            </tr>
          </thead>
          <tbody>
            {visible.map((r) => {
              const sig = r.q < ALPHA;
              const up = r.z > 0;
              return (
                <tr key={`${r.track || ''}|${r.id}`} onClick={() => onPick(r.id)}
                  className={`ax-scan__row ${sig ? 'is-sig' : ''} ${r.id === activeId ? 'is-active' : ''}`}>
                  <th scope="row">
                    <button type="button" className="ax-scan__pick"
                      onClick={(e) => { e.stopPropagation(); onPick(r.id); }}
                      aria-pressed={r.id === activeId} title="Show this trend in the chart above">
                      <span className="ax-scan__group">{scanGroup(r)}</span>
                      <span className="ax-scan__label">{scanLabel(r)}</span>
                    </button>
                  </th>
                  {split && (
                    <td className="ax-scan__track"><TrackKey dash={dashOf(r.track)} />{r.track}</td>
                  )}
                  <td><Sparkline points={r.points} yearMin={yearMin} yearMax={yearMax} color={r.dimKey ? colorFor?.(r.dimKey, r.value) : null} /></td>
                  <td className="ax-num"><PP value={r.change} /></td>
                  <td className="ax-num">{fmtP(r.p).replace(/^= /, '')}</td>
                  <td className="ax-num ax-scan__q">{fmtP(r.q).replace(/^= /, '')}</td>
                  <td>
                    <span className="ax-verdict">
                      <span className="ax-verdict__icon" aria-hidden="true">{sig ? (up ? '↑' : '↓') : '–'}</span>
                      {sig ? `Significant ${up ? 'rise' : 'fall'}` : 'Not significant'}
                    </span>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </section>
  );
}

export default function AnalysisPage() {
  const [papers, setPapers] = useState(null);
  const [config, setConfig] = useState(null);
  const [params, update] = useUrlState();
  const { filters } = useFilters();
  const [dir, setDir] = useState(1);
  const touch = useRef(null);
  const carouselRef = useRef(null);
  useBubbleMotion(carouselRef, Boolean(papers && config));
  const colorFor = useMemo(() => makeColorFor(config || {}, papers), [config, papers]);
  const { shapes } = useShapes();
  const shapeFor = useMemo(() => (shapes ? makeShapeFor(config || {}, papers) : null), [shapes, config, papers]);

  const activeIndex = Math.max(0, VIEWS.findIndex((v) => v.id === params.get('view')));
  const [aboutOpen, setAboutOpen] = useState(false);

  useEffect(() => {
    Promise.all([loadPapers(), loadConfig()]).then(([p, c]) => {
      setPapers(p);
      setConfig(c);
    });
  }, []);

  const scoped = useMemo(() => (papers ? papers.filter((p) => matchesFilters(p, filters)) : []), [papers, filters]);

  const goTo = (i) => {
    const next = clamp(i, 0, VIEWS.length - 1);
    if (next === activeIndex) return;
    setDir(next > activeIndex ? 1 : -1);
    update({ view: next === 0 ? null : VIEWS[next].id });
  };

  const filterNote = activeFilterCountOf(filters) > 0
    ? FILTER_FACETS.filter((f) => filters[f.key]?.length)
      .map((f) => `${f.label}: ${filters[f.key].map(humanize).join(', ')}`).join(' · ')
    : null;

  const onTouchStart = (e) => {
    if (e.target.closest('.ax-matrix__scroll, .ax-table-wrap, select')) { touch.current = null; return; }
    const t = e.touches[0];
    touch.current = { x: t.clientX, y: t.clientY };
  };
  const onTouchEnd = (e) => {
    if (!touch.current) return;
    const t = e.changedTouches[0];
    const dx = t.clientX - touch.current.x;
    const dy = t.clientY - touch.current.y;
    touch.current = null;
    if (Math.abs(dx) > 60 && Math.abs(dx) > Math.abs(dy) * 1.5) goTo(activeIndex + (dx < 0 ? 1 : -1));
  };

  if (!papers || !config) {
    return (
      <div className="main-layout">
        <div className="loading"><div className="loading__spinner" /><p>Loading...</p></div>
      </div>
    );
  }

  const years = scoped.map((p) => p.metadata?.year).filter(Boolean);

  return (
    <div className="main-layout">
      <Header config={config} />
      <main className="main-content ax-page">
        <div className="ax-header">
          <div className="ax-header__text">
            <h1>Patterns &amp; Trends</h1>
            <p className="graph-page__description">How codes co-occur and how practices change over time.</p>
          </div>
          <div className="ax-header__stats">
            <div className="ax-mini-stat">
              <span className="ax-mini-stat__value">{scoped.length}</span>
              <span className="ax-mini-stat__label">Papers</span>
            </div>
            <div className="ax-mini-stat">
              <span className="ax-mini-stat__value">{years.length ? `${Math.min(...years)}–${Math.max(...years)}` : '—'}</span>
              <span className="ax-mini-stat__label">Year range</span>
            </div>
          </div>
        </div>

        <FilterBar papers={papers} config={config} />

        <div className="ax-nav">
          <div className="ax-tabs" role="tablist" aria-label="Analysis views"
            onKeyDown={(e) => {
              if (e.key === 'ArrowRight') goTo(activeIndex + 1);
              if (e.key === 'ArrowLeft') goTo(activeIndex - 1);
            }}>
            {VIEWS.map((v, i) => (
              <button key={v.id} type="button" role="tab" id={`ax-tab-${v.id}`} aria-controls={`ax-panel-${v.id}`}
                aria-selected={i === activeIndex} tabIndex={i === activeIndex ? 0 : -1}
                className={`ax-tabs__tab ${i === activeIndex ? 'ax-tabs__tab--active' : ''}`} onClick={() => goTo(i)}>
                {v.label}
              </button>
            ))}
          </div>
          <AboutToggle open={aboutOpen} onToggle={() => setAboutOpen((o) => !o)}
            panelId={VIEWS[activeIndex].id === 'trends' ? 'tr-about' : 'ct-about'} />
        </div>

        <div className="ax-carousel" ref={carouselRef} onTouchStart={onTouchStart} onTouchEnd={onTouchEnd}>
          {VIEWS.map((v, i) => (
            <section key={v.id} id={`ax-panel-${v.id}`} role="tabpanel" aria-labelledby={`ax-tab-${v.id}`}
              hidden={i !== activeIndex}
              className={`ax-panel ${dir > 0 ? 'ax-panel--from-right' : 'ax-panel--from-left'}`}>
              {scoped.length === 0 ? (
                <div className="ax-frame"><div className="ax-empty">No papers match the current filters.</div></div>
              ) : (
                <>
                  {v.id === 'cooccurrence' && <CooccurrenceView papers={scoped} colorFor={colorFor} shapeFor={shapeFor} filterNote={filterNote} aboutOpen={aboutOpen} />}
                  {v.id === 'trends' && <TrendsView papers={scoped} colorFor={colorFor} aboutOpen={aboutOpen} />}
                </>
              )}
            </section>
          ))}
        </div>

        <div className="ax-dots" aria-hidden="true">
          {VIEWS.map((v, i) => (
            <button key={v.id} type="button" tabIndex={-1} className={`ax-dots__dot ${i === activeIndex ? 'is-on' : ''}`}
              onClick={() => goTo(i)} />
          ))}
        </div>
      </main>
    </div>
  );
}
