import { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { FILTER_FACETS } from './facets';

const FilterContext = createContext(null);
const PREFIX = 'f_';

function readFromSearch(search) {
  const p = new URLSearchParams(search);
  const out = {};
  FILTER_FACETS.forEach((f) => {
    const raw = p.get(PREFIX + f.key);
    if (raw) out[f.key] = raw.split(',').filter(Boolean);
  });
  return out;
}

function writeToSearch(search, filters) {
  const p = new URLSearchParams(search);
  FILTER_FACETS.forEach((f) => {
    const sel = filters[f.key];
    if (sel && sel.length) p.set(PREFIX + f.key, sel.join(','));
    else p.delete(PREFIX + f.key);
  });
  const s = p.toString();
  return s ? `?${s}` : '';
}

export function FilterProvider({ children }) {
  const location = useLocation();
  const navigate = useNavigate();
  const [filters, setFilters] = useState(() => readFromSearch(location.search));

  useEffect(() => {
    const next = writeToSearch(location.search, filters);
    const current = location.search || '';
    if (next !== current) {
      navigate({ pathname: location.pathname, search: next, hash: location.hash }, { replace: true, state: location.state });
    }
  }, [filters, location.pathname, location.search, location.hash, location.state, navigate]);

  useEffect(() => {
    const fromUrl = readFromSearch(location.search);
    if (!Object.keys(fromUrl).length) return;
    setFilters((prev) => (writeToSearch('', prev) === writeToSearch('', fromUrl) ? prev : fromUrl));
  }, [location.search]);

  const toggle = useCallback((key, value) => {
    setFilters((prev) => {
      const cur = prev[key] || [];
      const nextVals = cur.includes(value) ? cur.filter((v) => v !== value) : [...cur, value];
      const next = { ...prev, [key]: nextVals };
      if (!nextVals.length) delete next[key];
      return next;
    });
  }, []);

  const clear = useCallback(() => setFilters({}), []);

  const value = useMemo(() => ({ filters, toggle, clear }), [filters, toggle, clear]);
  return <FilterContext.Provider value={value}>{children}</FilterContext.Provider>;
}

export function useFilters() {
  const ctx = useContext(FilterContext);
  if (!ctx) throw new Error('useFilters must be used within a FilterProvider');
  return ctx;
}
