import { useMemo, useState } from 'react';
import { humanize } from '@/lib/humanize';
import { isAnonymized } from '@/lib/filters';
import { SIMILARITY_DIMENSIONS, buildSimilarity } from '@/lib/similarity';
import { AboutPanel, AboutToggle } from '@/components/HowToRead';

const SIZES = [5, 10, 20];
const MAX_SUGGESTIONS = 8;
const MAX_GROUPS = 3;

function paperName(paper) {
  if (paper.metadata?.title) return paper.metadata.title;
  return `Anonymized paper (${[paper.metadata?.year, paper.metadata?.track].filter(Boolean).join(', ')})`;
}

function paperMeta(paper) {
  if (isAnonymized(paper)) return '';
  return [paper.metadata?.authors?.slice(0, 2).join(', ') + (paper.metadata?.authors?.length > 2 ? ' et al.' : ''), paper.metadata?.year]
    .filter(Boolean)
    .join(' · ');
}

export default function SimilarPapers({ papers, candidates, targetId, onTargetChange, size, onSizeChange, onOpen, filtered }) {
  const [query, setQuery] = useState('');
  const [aboutOpen, setAboutOpen] = useState(false);
  const similarity = useMemo(() => buildSimilarity(papers), [papers]);
  const target = papers.find((p) => p._id === targetId) || null;

  const searchable = useMemo(() => papers.filter((p) => !isAnonymized(p)), [papers]);
  const suggestions = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return [];
    return searchable
      .filter((p) => [p.metadata?.title, ...(p.metadata?.authors || []), p.metadata?.doi_or_url].join(' ').toLowerCase().includes(q))
      .slice(0, MAX_SUGGESTIONS);
  }, [query, searchable]);

  const results = useMemo(() => (target ? similarity.mostSimilar(target, candidates).slice(0, size) : []), [target, candidates, size, similarity]);

  const choose = (id) => {
    setQuery('');
    onTargetChange(id);
  };

  return (
    <section className="ax-page ax-frame ax-scan similar-papers" id="similar" aria-labelledby="similar-title">
      <div className="ax-toolbar ax-scan__toolbar">
        <div className="ax-scan__title">
          <h2 id="similar-title">Most Similar Papers</h2>
          {filtered && <p>Only papers that match the filters are compared.</p>}
        </div>
        <div className="graph-controls__spacer" />
        <div className="ax-field">
          <span className="ax-field__label">Show</span>
          <div className="filters-panel__chips" role="group" aria-label="Number of similar papers">
            {SIZES.map((n) => (
              <button key={n} type="button" className={`filter-chip ${size === n ? 'filter-chip--active' : ''}`}
                onClick={() => onSizeChange(n)} aria-pressed={size === n}>
                Top {n}
              </button>
            ))}
          </div>
        </div>
        <AboutToggle open={aboutOpen} onToggle={() => setAboutOpen((o) => !o)} panelId="similar-about" />
      </div>

      <AboutPanel open={aboutOpen} id="similar-about">
        <p className="similar-papers__about">
          Pick a paper to rank the collection by how alike it is coded. Similarity is the average agreement across the{' '}
          {SIMILARITY_DIMENSIONS.length} coded attributes ({SIMILARITY_DIMENSIONS.map((d) => humanize(d.key)).join(', ')});
          rare codes count more than common ones, and 100% means coded identically. Not listed? Add your paper with + Add Paper
          on Overview.
        </p>
      </AboutPanel>

      <div className="similar-papers__pick">
        {target ? (
          <div className="similar-papers__target">
            <span className="similar-papers__label">Papers most similar to</span>
            <button type="button" className="similar-papers__target-name" onClick={() => onOpen(target._id)}
              title="Show this paper's details">
              {paperName(target)}
            </button>
            {paperMeta(target) && <span className="similar-papers__meta">{paperMeta(target)}</span>}
            <button type="button" className="btn btn--ghost btn--sm" onClick={() => onTargetChange(null)}>Change paper</button>
          </div>
        ) : (
          <div className="similar-papers__search">
            <input
              type="search"
              className="toolbar__search"
              placeholder="Search a paper by title, author or DOI…"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              aria-label="Search a paper to compare"
            />
            {suggestions.length > 0 && (
              <ul className="similar-papers__suggestions" role="listbox">
                {suggestions.map((p) => (
                  <li key={p._id}>
                    <button type="button" onClick={() => choose(p._id)}>
                      <span>{paperName(p)}</span>
                      {paperMeta(p) && <span className="similar-papers__meta">{paperMeta(p)}</span>}
                    </button>
                  </li>
                ))}
              </ul>
            )}
            {query.trim() && !suggestions.length && <p className="ax-scan__note">No listed paper matches “{query.trim()}”.</p>}
          </div>
        )}
      </div>

      {target && results.length > 0 && (
        <div className="ax-table-wrap">
          <table className="ax-table ax-scan__table">
            <thead>
              <tr>
                <th scope="col" className="ax-num">#</th>
                <th scope="col">Paper</th>
                <th scope="col">Similarity</th>
                <th scope="col">Coded alike</th>
                <th scope="col">Differs in</th>
              </tr>
            </thead>
            <tbody>
              {results.map((r, i) => {
                const groups = r.attributes.filter((a) => a.shared.length);
                const differs = r.attributes.filter((a) => a.score === 0).map((a) => humanize(a.key));
                const openable = !isAnonymized(r.paper);
                return (
                  <tr key={r.paper._id} className="ax-scan__row"
                    onClick={openable ? () => onOpen(r.paper._id) : undefined}
                    style={openable ? undefined : { cursor: 'default' }}>
                    <td className="ax-num">{i + 1}</td>
                    <th scope="row">
                      <span className="similar-papers__paper">
                        <span>{paperName(r.paper)}</span>
                        {paperMeta(r.paper) && <span className="similar-papers__meta">{paperMeta(r.paper)}</span>}
                      </span>
                    </th>
                    <td>
                      <span className="similar-papers__score">
                        <span className="similar-papers__bar"><span style={{ width: `${Math.round(r.score * 100)}%` }} /></span>
                        {Math.round(r.score * 100)}%
                      </span>
                    </td>
                    <td className="similar-papers__cell">
                      {groups.slice(0, MAX_GROUPS).map((a) => (
                        <span key={a.key} className="similar-papers__group">
                          <span className="similar-papers__attr">{humanize(a.key)}:</span> {a.shared.map(humanize).join(', ')}
                        </span>
                      ))}
                      {groups.length > MAX_GROUPS && (
                        <span className="similar-papers__more" title={groups.slice(MAX_GROUPS).map((a) => `${humanize(a.key)}: ${a.shared.map(humanize).join(', ')}`).join('\n')}>
                          +{groups.length - MAX_GROUPS} more attributes
                        </span>
                      )}
                    </td>
                    <td className="similar-papers__cell">{differs.join(', ') || '—'}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </section>
  );
}
