
export const MISSING = '__missing__';

const asArray = (v) => (Array.isArray(v) ? v : v === undefined || v === null || v === '' ? [] : [v]);

function implementationStatus(a) {
  const impl = a.implementation;
  if (!impl || impl.existence === undefined || impl.existence === null) return [];
  if (!impl.existence) return ['no_implementation'];
  if (impl.availability === true) return ['implementation_available'];
  if (impl.availability === false) return ['implementation_not_available'];
  return ['implementation_availability_unknown'];
}

const artifactDim = (getter) => ({ level: 'artifact', getter });
const paperDim = (getter) => ({ level: 'paper', getter });

export const DIMENSIONS = [
  { key: 'type_of_artifact', ...artifactDim((a) => a.type_of_artifact) },
  { key: 'research_method', ...artifactDim((a) => a.research_method?.methods) },
  { key: 'evaluation_method', ...artifactDim((a) => a.evaluation_method) },
  { key: 'data_type', ...artifactDim((a) => a.data_collection?.data_type) },
  { key: 'threats_to_validity', ...artifactDim((a) => a.threats_to_validity), emptyValue: 'none_discussed' },
  { key: 'implementation', ...artifactDim(implementationStatus) },
  { key: 'type_of_inquiry', ...paperDim((p) => p.contribution?.focus_intent?.type_of_inquiry) },
  { key: 'type_of_theory', ...paperDim((p) => p.contribution?.research_components?.type_of_theory) },
  { key: 'emphasis', ...paperDim((p) => p.contribution?.research_components?.emphasis) },
  { key: 'track', ...paperDim((p) => p.metadata?.track) },
  { key: 'year', ...paperDim((p) => p.metadata?.year), numeric: true },
];

export const getDimension = (key) => DIMENSIONS.find((d) => d.key === key);

export function buildUnits(papers, unit) {
  if (unit === 'artifact') {
    return papers.flatMap((paper) =>
      (paper.contribution?.artifacts || []).map((artifact) => ({ paper, artifacts: [artifact] }))
    );
  }
  return papers.map((paper) => ({ paper, artifacts: paper.contribution?.artifacts || [] }));
}

export function unitValues(unit, dim) {
  let values;
  if (dim.level === 'paper') {
    values = asArray(dim.getter(unit.paper));
  } else {
    values = [...new Set(unit.artifacts.flatMap((a) => asArray(dim.getter(a))))];
  }
  if (values.length) return values.map(String);
  return [dim.emptyValue || MISSING];
}

function orderValues(counts, dim) {
  const entries = [...counts.entries()];
  entries.sort((a, b) => {
    if (a[0] === MISSING) return 1;
    if (b[0] === MISSING) return -1;
    if (dim.numeric) return Number(a[0]) - Number(b[0]);
    return b[1] - a[1] || a[0].localeCompare(b[0]);
  });
  return entries.map(([v]) => v);
}

export function crossTab(units, rowDim, colDim) {
  const rowCounts = new Map();
  const colCounts = new Map();
  const cells = new Map();
  let multiRow = 0;
  let multiCol = 0;

  units.forEach((u) => {
    const rv = unitValues(u, rowDim);
    const cv = unitValues(u, colDim);
    if (rv.length > 1) multiRow += 1;
    if (cv.length > 1) multiCol += 1;
    rv.forEach((r) => rowCounts.set(r, (rowCounts.get(r) || 0) + 1));
    cv.forEach((c) => colCounts.set(c, (colCounts.get(c) || 0) + 1));
    rv.forEach((r) =>
      cv.forEach((c) => {
        const k = `${r}\u0000${c}`;
        cells.set(k, (cells.get(k) || 0) + 1);
      })
    );
  });

  return {
    n: units.length,
    rows: orderValues(rowCounts, rowDim),
    cols: orderValues(colCounts, colDim),
    rowTotals: rowCounts,
    colTotals: colCounts,
    cell: (r, c) => cells.get(`${r}\u0000${c}`) || 0,
    multiRow,
    multiCol,
  };
}

export function wilson(k, n, z = 1.959964) {
  if (n === 0) return { p: NaN, lo: NaN, hi: NaN };
  const p = k / n;
  const z2 = z * z;
  const denom = 1 + z2 / n;
  const center = (p + z2 / (2 * n)) / denom;
  const half = (z * Math.sqrt((p * (1 - p)) / n + z2 / (4 * n * n))) / denom;
  return { p, lo: Math.max(0, center - half), hi: Math.min(1, center + half) };
}

function erf(x) {
  const sign = x < 0 ? -1 : 1;
  const t = 1 / (1 + 0.3275911 * Math.abs(x));
  const y =
    1 -
    ((((1.061405429 * t - 1.453152027) * t + 1.421413741) * t - 0.284496736) * t + 0.254829592) *
      t *
      Math.exp(-x * x);
  return sign * y;
}

const normalCdf = (z) => 0.5 * (1 + erf(z / Math.SQRT2));

export function cochranArmitage(groups) {
  const N = groups.reduce((s, g) => s + g.n, 0);
  const R = groups.reduce((s, g) => s + g.k, 0);
  if (N === 0 || R === 0 || R === N || groups.length < 2) return null;
  const pBar = R / N;
  const xBar = groups.reduce((s, g) => s + g.n * g.x, 0) / N;
  const T = groups.reduce((s, g) => s + g.k * (g.x - xBar), 0);
  const varT = pBar * (1 - pBar) * groups.reduce((s, g) => s + g.n * (g.x - xBar) ** 2, 0);
  if (varT <= 0) return null;
  const z = T / Math.sqrt(varT);
  return { z, p: 2 * (1 - normalCdf(Math.abs(z))), N };
}

const anyArtifact = (pred) => (paper) => (paper.contribution?.artifacts || []).some(pred);

const EMPIRICAL_EVAL = new Set([
  'controlled_experiment',
  'field_experiment',
  'benchmark',
  'technical_experiment',
  'case_study',
  'data_science',
  'questionnaire',
  'interview',
  'focus_group',
  'grounded_theory',
]);

export const INDICATORS = [
  {
    id: 'impl_available',
    label: 'Implementation publicly available',
    test: anyArtifact((a) => a.implementation?.availability === true),
  },
  {
    id: 'impl_exists',
    label: 'Implementation exists',
    test: anyArtifact((a) => a.implementation?.existence === true),
  },
  {
    id: 'data_accessible',
    label: 'Data publicly accessible',
    test: anyArtifact((a) => a.data_collection?.data_accessibility === true),
  },
  {
    id: 'material_accessible',
    label: 'Material publicly accessible',
    test: anyArtifact((a) => a.data_collection?.material_accessibility === true),
  },
  {
    id: 'real_world_data',
    label: 'Uses real-world data',
    test: anyArtifact((a) => (a.data_collection?.data_type || []).includes('real_world_data')),
  },
  {
    id: 'ttv',
    label: 'Discusses threats to validity',
    test: anyArtifact((a) => (a.threats_to_validity || []).length > 0),
  },
  {
    id: 'empirical_eval',
    label: 'Empirical evaluation (beyond verification / examples)',
    test: anyArtifact((a) => (a.evaluation_method || []).some((m) => EMPIRICAL_EVAL.has(m))),
  },
  {
    id: 'participants',
    label: 'Involves human participants',
    test: anyArtifact((a) => (a.data_collection?.participants?.total_participants || 0) > 0),
  },
];

export const EMPIRICAL_EVAL_METHODS = [...EMPIRICAL_EVAL];

export function valueIndicator(dim, value) {
  return {
    id: `dim:${dim.key}:${value}`,
    test: (paper) => unitValues(buildUnits([paper], 'paper')[0], dim).includes(value),
  };
}

export function resolveIndicator(id) {
  const fixed = INDICATORS.find((i) => i.id === id);
  if (fixed) return fixed;
  const [, key, ...rest] = id.split(':');
  const dim = getDimension(key);
  return dim ? valueIndicator(dim, rest.join(':')) : INDICATORS[0];
}

export function yearlyTrend(papers, indicator) {
  const byYear = new Map();
  papers.forEach((p) => {
    const y = p.metadata?.year;
    if (!y) return;
    const g = byYear.get(y) || { x: y, n: 0, k: 0 };
    g.n += 1;
    if (indicator.test(p)) g.k += 1;
    byYear.set(y, g);
  });
  return [...byYear.values()]
    .sort((a, b) => a.x - b.x)
    .map((g) => ({ ...g, ...wilson(g.k, g.n) }));
}

export function toCsv(rows) {
  const esc = (v) => {
    const s = v === undefined || v === null ? '' : String(v);
    return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
  };
  return rows.map((r) => r.map(esc).join(',')).join('\n');
}

export function downloadCsv(filename, rows) {
  const blob = new Blob([toCsv(rows)], { type: 'text/csv;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}

/**
 * Adjusts p-values for multiple testing. Returns adjusted values in the
 * input order. 'bh' = Benjamini–Hochberg (false discovery rate), 'holm' =
 * Holm–Bonferroni (family-wise error), 'none' = unchanged.
 */
export function adjustPValues(ps, method = 'bh') {
  const m = ps.length;
  if (method === 'none' || m === 0) return [...ps];
  const order = ps.map((p, i) => [p, i]).sort((a, b) => a[0] - b[0]);
  const adj = new Array(m);
  if (method === 'holm') {
    let running = 0;
    order.forEach(([p, i], rank) => {
      running = Math.max(running, Math.min(1, (m - rank) * p));
      adj[i] = running;
    });
    return adj;
  }
  let running = 1;
  for (let rank = m - 1; rank >= 0; rank -= 1) {
    const [p, i] = order[rank];
    running = Math.min(running, (p * m) / (rank + 1));
    adj[i] = Math.min(1, running);
  }
  return adj;
}

/**
 * Runs the trend test for every reporting indicator and every coded value
 * (all dimensions except year) that at least `minPapers` papers have.
 * A coded value that counts exactly the same papers per year as an earlier
 * candidate — or exactly the complement (e.g. "none discussed" vs "discusses
 * threats to validity") — is the same test and is listed only once.
 * Returns one row per test with the share per year, the fitted change over
 * the whole period (the least-squares line through the yearly shares,
 * weighted by papers per year, so its sign always matches the test), and
 * raw and adjusted p.
 */
export function trendScan(papers, { method = 'bh', minPapers = 5 } = {}) {
  const units = buildUnits(papers, 'paper');
  const candidates = INDICATORS.map((ind) => ({ id: ind.id, label: ind.label, group: 'Empirical & Experimental Evidence', indicator: ind }));
  DIMENSIONS.filter((d) => d.key !== 'year').forEach((d) => {
    const counts = new Map();
    units.forEach((u) => unitValues(u, d).forEach((v) => v !== MISSING && counts.set(v, (counts.get(v) || 0) + 1)));
    [...counts.entries()].filter(([, n]) => n >= minPapers).forEach(([v]) => {
      const id = `dim:${d.key}:${v}`;
      candidates.push({ id, dimKey: d.key, value: v, group: d.key, indicator: resolveIndicator(id) });
    });
  });

  const seen = new Set();
  const rows = candidates.map((c) => {
    const points = yearlyTrend(papers, c.indicator);
    const sig = points.map((g) => `${g.x}:${g.k}`).join('|');
    const mirror = points.map((g) => `${g.x}:${g.n - g.k}`).join('|');
    if (seen.has(sig) || seen.has(mirror)) return null;
    seen.add(sig);
    const test = cochranArmitage(points);
    const total = points.reduce((s, g) => ({ n: s.n + g.n, k: s.k + g.k }), { n: 0, k: 0 });
    const fit = fittedChange(points);
    return {
      id: c.id, label: c.label, dimKey: c.dimKey, value: c.value, group: c.group, points,
      share: total.n ? total.k / total.n : NaN,
      change: fit.change, changeFrom: fit.from, changeTo: fit.to,
      z: test?.z ?? null, p: test?.p ?? null,
    };
  }).filter((r) => r && r.p !== null);

  const adjusted = adjustPValues(rows.map((r) => r.p), method);
  rows.forEach((r, i) => { r.q = adjusted[i]; });
  return rows.sort((a, b) => a.q - b.q || a.p - b.p);
}

/**
 * trendScan for each track separately. All tracks' tests are adjusted for
 * multiple testing together (tracks × indicators), since they are read side
 * by side. Each row gets a `track` field.
 */
export function trendScanByTrack(papers, tracks, { method = 'bh', minPapers = 5 } = {}) {
  const rows = tracks.flatMap((track) =>
    trendScan(papers.filter((p) => p.metadata?.track === track), { method: 'none', minPapers })
      .map((r) => ({ ...r, track }))
  );
  const adjusted = adjustPValues(rows.map((r) => r.p), method);
  rows.forEach((r, i) => { r.q = adjusted[i]; });
  return rows.sort((a, b) => a.q - b.q || a.p - b.p);
}

/**
 * Change over the whole period along the least-squares line through the
 * yearly shares, weighted by papers per year. Its sign always matches the
 * Cochran–Armitage test statistic. Returns { change, from, to }.
 */
export function fittedChange(points) {
  const n = points.reduce((s, g) => s + g.n, 0);
  const k = points.reduce((s, g) => s + g.k, 0);
  const from = points[0]?.x;
  const to = points[points.length - 1]?.x;
  if (!n || !(to > from)) return { change: null, from, to };
  const xBar = points.reduce((s, g) => s + g.n * g.x, 0) / n;
  const sxx = points.reduce((s, g) => s + g.n * (g.x - xBar) ** 2, 0);
  const sxy = points.reduce((s, g) => s + (g.k - g.n * (k / n)) * (g.x - xBar), 0);
  return { change: sxx > 0 ? (sxy / sxx) * (to - from) : null, from, to };
}

// --- Associations between two coded values (co-occurrence) ------------------

const logFactCache = [0];
function logFact(n) {
  for (let i = logFactCache.length; i <= n; i += 1) logFactCache[i] = logFactCache[i - 1] + Math.log(i);
  return logFactCache[n];
}

/**
 * Two-sided Fisher's exact test for the 2×2 table [[a, b], [c, d]]: the
 * probability of a table at least as extreme as the observed one, given the
 * row and column totals.
 */
export function fisherExact(a, b, c, d) {
  const r1 = a + b;
  const c1 = a + c;
  const n = a + b + c + d;
  const lo = Math.max(0, r1 + c1 - n);
  const hi = Math.min(r1, c1);
  const logP = (x) =>
    logFact(r1) + logFact(n - r1) + logFact(c1) + logFact(n - c1)
    - logFact(n) - logFact(x) - logFact(r1 - x) - logFact(c1 - x) - logFact(n - r1 - c1 + x);
  const observed = logP(a);
  let p = 0;
  for (let x = lo; x <= hi; x += 1) {
    const lp = logP(x);
    if (lp <= observed + 1e-7) p += Math.exp(lp);
  }
  return Math.min(1, p);
}

/**
 * Tests every pair (row value × column value) for association. Counts only
 * units coded on both dimensions (an uncoded unit is unknown, not "without
 * the value"). For each pair: observed count, expected count if the two were
 * independent, ratio observed/expected, Fisher's exact p and p adjusted for
 * testing all pairs at once.
 */
export function associationScan(units, rowDim, colDim, { method = 'bh' } = {}) {
  const coded = units
    .map((u) => ({ rv: unitValues(u, rowDim).filter((v) => v !== MISSING), cv: unitValues(u, colDim).filter((v) => v !== MISSING) }))
    .filter((u) => u.rv.length && u.cv.length);
  const n = coded.length;
  const rowN = new Map();
  const colN = new Map();
  const both = new Map();
  coded.forEach(({ rv, cv }) => {
    rv.forEach((r) => rowN.set(r, (rowN.get(r) || 0) + 1));
    cv.forEach((c) => colN.set(c, (colN.get(c) || 0) + 1));
    rv.forEach((r) => cv.forEach((c) => { const k = `${r}\u0000${c}`; both.set(k, (both.get(k) || 0) + 1); }));
  });

  const sameDim = rowDim === colDim;
  const rows = [];
  rowN.forEach((nr, r) => colN.forEach((nc, c) => {
    if (sameDim && r >= c) return;
    const a = both.get(`${r}\u0000${c}`) || 0;
    const b = nr - a;
    const cc = nc - a;
    const d = n - nr - nc + a;
    const expected = (nr * nc) / n;
    rows.push({
      r, c, observed: a, expected, rowN: nr, colN: nc, n,
      ratio: expected > 0 ? a / expected : NaN,
      // Odds ratio with +0.5 on every cell so empty cells stay finite.
      oddsRatio: ((a + 0.5) * (d + 0.5)) / ((b + 0.5) * (cc + 0.5)),
      p: fisherExact(a, b, cc, d),
    });
  }));
  const adjusted = adjustPValues(rows.map((x) => x.p), method);
  rows.forEach((x, i) => { x.q = adjusted[i]; x.more = x.observed > x.expected; });
  return { n, rows: rows.sort((x, y) => x.q - y.q || x.p - y.p) };
}

export function choiceProfile(papers, dim, unit = 'paper') {
  let coded = 0;
  let multi = 0;
  const counts = new Map();
  buildUnits(papers, unit).forEach((u) => {
    const values = unitValues(u, dim).filter((v) => v !== MISSING);
    if (values.length) coded += 1;
    if (values.length > 1) multi += 1;
    values.forEach((v) => counts.set(v, (counts.get(v) || 0) + 1));
  });
  return { coded, multiShare: coded ? multi / coded : 0, counts };
}
